# ====== ModelRouter ======
class ModelRouter:
    """多模型路由"""
    def __init__(self):
        self.models = {}  # task_type -> model_name
        self.default = ""
        self.api_url = ""
        self.api_key = ""

    def configure(self, default, api_url, api_key, task_models=None):
        self.default = default
        self.api_url = api_url
        self.api_key = api_key
        if task_models:
            self.models = task_models

    def get_for_task(self, task_type):
        """按任务类型返回模型"""
        return self.models.get(task_type, self.default)

    def set_for_task(self, task_type, model_name):
        self.models[task_type] = model_name

    def list(self):
        res = {"default": self.default, "task_models": dict(self.models)}
        return res

