# ====== SmartCompressor ======
def _content_to_text(content):
    """把字符串/多模态 content 统一转成可展示、可计数的文本。"""
    if content is None:
        return ""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for item in content:
            if isinstance(item, dict):
                item_type = item.get("type")
                if item_type in ("text", "output_text") and item.get("text"):
                    parts.append(str(item.get("text")))
                elif item_type == "image_url":
                    parts.append("[image]")
                else:
                    try:
                        parts.append(json.dumps(item, ensure_ascii=False))
                    except:
                        parts.append(str(item))
            else:
                parts.append(str(item))
        return "\n".join(p for p in parts if p)
    if isinstance(content, dict):
        try:
            return json.dumps(content, ensure_ascii=False)
        except:
            return str(content)
    return str(content)

class SmartCompressor:
    """智能上下文压缩"""
    @staticmethod
    def compress(messages, max_chars=16000):
        """保留系统提示+最近N轮+压缩中间部分，不打断 tool_call 配对"""
        chars = sum(len(_content_to_text(m.get("content",""))) for m in messages if isinstance(m, dict))
        if chars <= max_chars:
            return messages

        # 始终保留system
        result = [messages[0]]
        remaining = messages[1:]
        used = len(_content_to_text(messages[0].get("content",""))) if isinstance(messages[0], dict) else 0

        # 先把消息分组：tool_call 配对作为原子单位
        # assistant(tool_calls) + 后续所有 tool 消息视为一组
        groups = []
        i = 0
        while i < len(remaining):
            m = remaining[i]
            if m.get("role") == "assistant" and m.get("tool_calls"):
                # 找到这个 group：assistant + 紧随其后的 tool 消息
                group = [m]
                i += 1
                while i < len(remaining) and remaining[i].get("role") == "tool":
                    group.append(remaining[i])
                    i += 1
                groups.append(group)
            elif m.get("role") == "tool":
                # 孤立的 tool 消息（没有前驱 assistant），可能是压缩后的残留
                # 单独成组以防遍历时跳过
                groups.append([m])
                i += 1
            else:
                groups.append([m])
                i += 1

        # 从后往前分配组（最近优先）
        recent = []
        mid = []
        for group in reversed(groups):
            gsize = sum(len(_content_to_text(m.get("content",""))) for m in group if isinstance(m, dict))
            if used + gsize <= max_chars * 0.6:
                recent.insert(0, group)
                used += gsize
            else:
                mid.insert(0, group)

        # 压缩中间组：每组作为整体处理
        compressed_groups = []
        for group in mid:
            compressed_group = []
            for m in group:
                content = _content_to_text(m.get("content",""))
                new_m = {"role": m["role"], "content": content[:100] + "...[压缩]" if len(content) > 100 else content}
                # tool 消息必须保留 tool_call_id
                if m.get("role") == "tool" and m.get("tool_call_id"):
                    new_m["tool_call_id"] = m["tool_call_id"]
                # assistant tool_calls 消息 content 必须为空字符串
                if m.get("role") == "assistant" and m.get("tool_calls"):
                    new_m["tool_calls"] = m["tool_calls"]
                    new_m["content"] = ""  # tool_calls 消息 content 必须空
                compressed_group.append(new_m)
            compressed_groups.append(compressed_group)

        # 如果还超，继续从中间压缩（按组删除）
        flat_recent = []
        for group in recent:
            flat_recent.extend(group)
        flat_compressed = []
        for group in compressed_groups:
            flat_compressed.extend(group)
        total = sum(len(_content_to_text(m.get("content",""))) for m in result + flat_compressed + flat_recent if isinstance(m, dict))
        while total > max_chars and len(compressed_groups) > 0:
            dropped_group = compressed_groups.pop(0)
            total -= sum(len(_content_to_text(m.get("content",""))) for m in dropped_group if isinstance(m, dict))
            if total <= 0:
                break

        flat_compressed = []
        for group in compressed_groups:
            flat_compressed.extend(group)
        return result + flat_compressed + flat_recent


def _sanitize_messages_for_api(messages):
    """修复被压缩或历史污染打断的 tool_call / tool 配对，避免 API 400。"""
    sanitized = []
    pending_tool_ids = set()
    for m in messages or []:
        if not isinstance(m, dict):
            continue
        role = m.get("role")
        if role == "assistant" and m.get("tool_calls"):
            tool_ids = []
            for tc in m.get("tool_calls") or []:
                if not isinstance(tc, dict):
                    continue
                tc_id = tc.get("id")
                if tc_id:
                    tool_ids.append(tc_id)
            if tool_ids:
                pending_tool_ids.update(tool_ids)
            cleaned = dict(m)
            if cleaned.get("content") is None:
                cleaned["content"] = ""
            sanitized.append(cleaned)
            continue
        if role == "tool":
            tc_id = m.get("tool_call_id")
            if not tc_id or tc_id not in pending_tool_ids:
                continue
            sanitized.append(m)
            pending_tool_ids.discard(tc_id)
            continue
        sanitized.append(m)
        if role in ("user", "system"):
            pending_tool_ids.clear()
    return sanitized



# ====== Gateway ======
class Gateway:
    """后台守护模式"""
    def __init__(self):
        self.running = False
        self.mode = "interactive"  # interactive | daemon | once

    def start_daemon(self, agent_factory):
        """以守护模式运行"""
        self.running = True
        self.mode = "daemon"
        import threading
        def _loop():
            while self.running:
                try:
                    time.sleep(60)
                except: break
        t = threading.Thread(target=_loop, daemon=True)
        t.start()
        return {"ok": True, "mode": "daemon"}

    def stop(self):
        self.running = False
        self.mode = "interactive"

