class SessionStore:
    def __init__(self, data_dir):
        self.session_dir = os.path.join(data_dir, "sessions")
        self.index_file = os.path.join(data_dir, "session_index.json")
        os.makedirs(self.session_dir, exist_ok=True)
        self.index = self._load_index()
        self._current_file = None
    def _load_index(self):
        if os.path.exists(self.index_file):
            try:
                with open(self.index_file, encoding="utf-8") as f: return json.load(f)
            except: pass
        return {"sessions": [], "next_id": 1}
    def _save_index(self):
        with open(self.index_file, "w", encoding="utf-8") as f: json.dump(self.index, f, ensure_ascii=False, indent=2)
    def start_session(self):
        sid = self.index["next_id"]
        self.index["next_id"] = sid + 1
        info = {"id": sid, "started": datetime.datetime.now().isoformat(), "turns": 0, "file": f"session_{sid:04d}.jsonl"}
        self.index["sessions"].insert(0, info)
        if len(self.index["sessions"]) > 50:
            for old in self.index["sessions"][50:]:
                fp = os.path.join(self.session_dir, old["file"])
                if os.path.exists(fp): os.remove(fp)
            self.index["sessions"] = self.index["sessions"][:50]
        self._save_index()
        self._current_file = os.path.join(self.session_dir, info["file"])
        return sid
    def append(self, role, content):
        if not self._current_file: return
        entry = json.dumps({"role": role, "content": content[:2000], "time": time.time(), "user": get_user_identity()}, ensure_ascii=False)
        with open(self._current_file, "a", encoding="utf-8") as f: f.write(entry + "\n")
        for s in self.index["sessions"]:
            if s["file"] == os.path.basename(self._current_file):
                s["turns"] = (s.get("turns",0) or 0) + 1
                s["last"] = datetime.datetime.now().isoformat(); break
        self._save_index()
    def search(self, keyword):
        results = []
        for s in self.index["sessions"]:
            fpath = os.path.join(self.session_dir, s["file"])
            if not os.path.exists(fpath): continue
            try:
                with open(fpath, encoding="utf-8") as f:
                    for line in f:
                        if not line.strip(): continue
                        try:
                            entry = json.loads(line)
                            if keyword.lower() in entry.get("content","").lower():
                                results.append({"session":s["id"],"time":entry.get("time",""),"role":entry.get("role",""),"content":entry.get("content","")[:300]})
                        except: pass
            except: pass
        return results[:30]
    def get_recent(self, n=2):
        results = []
        for s in self.index["sessions"][:n]:
            fpath = os.path.join(self.session_dir, s["file"])
            if not os.path.exists(fpath): continue
            lines = []
            try:
                with open(fpath, encoding="utf-8") as f:
                    for i, line in enumerate(f):
                        if i >= 6: break
                        if line.strip():
                            try:
                                entry = json.loads(line)
                                lines.append(f"{'用户' if entry['role']=='user' else '你'}: {entry['content'][:200]}")
                            except: pass
            except: pass
            if lines: results.append({"session":s["id"],"dialogue":"\n".join(lines)})
        return results
    def get_stats(self):
        return {"total_sessions": len(self.index["sessions"]), "total_turns": sum(s.get("turns",0) for s in self.index["sessions"])}


# ========================================================================
# ExactPatch —— 精确文件编辑（9种策略/上下文/备份/语法检查/diff）
# ========================================================================
class ExactPatch:
    """Hermes 级精确文件编辑器"""

    @staticmethod
    def _normalize(s):
        """标准化空白用于模糊匹配"""
        return re.sub(r'\s+', ' ', s.strip())

    @staticmethod
    def _check_syntax(filepath, content=None):
        """检查文件语法（支持 .py .json .yaml）"""
        ext = os.path.splitext(filepath)[1].lower()
        if ext == '.py':
            try:
                compile(content or open(filepath, encoding='utf-8').read(), filepath, 'exec')
                return True, ""
            except SyntaxError as e:
                return False, f"第{e.lineno}行: {e.msg}"
        if ext == '.json':
            try:
                json.loads(content or open(filepath, encoding='utf-8').read())
                return True, ""
            except json.JSONDecodeError as e:
                return False, f"第{e.lineno}行: {e.msg}"
        return True, ""  # 其他格式跳过检查

    @staticmethod
    def _make_diff(filepath, old_text, new_text):
        """生成 unified diff"""
        old_lines = old_text.splitlines(True)
        new_lines = new_text.splitlines(True)
        diff = difflib.unified_diff(old_lines, new_lines,
                                     fromfile=f'a/{os.path.basename(filepath)}',
                                     tofile=f'b/{os.path.basename(filepath)}',
                                     lineterm='')
        return ''.join(diff)

    @classmethod
    def patch(cls, filepath, old_string, new_string, replace_all=False):
        """
        精确文件编辑，返回 {ok/error/diff/backup}
        支持9种匹配策略：
        1. 精确匹配
        2. 忽略行尾空白
        3. 忽略所有空白差异
        4. 忽略大小写
        5. 忽略大小写+空白
        6. 子串匹配
        7. 模糊（编辑距离容差1）
        8. 上下文辅助（取old_string前后行辅助定位）
        9. 正则模式
        """
        if not os.path.exists(filepath):
            return {"error": f"文件不存在: {filepath}"}

        with open(filepath, encoding="utf-8") as f:
            content = f.read()

        strategies = [
            ("精确匹配", lambda: content.count(old_string)),
            ("忽略尾随空白", lambda: content.count(old_string.rstrip() + '\n') + content.count(old_string.rstrip())),
            ("忽略大小写", lambda: len(re.findall(re.escape(old_string), content, re.IGNORECASE))),
            ("行尾统一", lambda: content.count(old_string.replace('\r\n', '\n'))),
            ("子串宽松", lambda: (1 if old_string.strip() in content else 0)),
        ]

        best_strategy = None
        best_count = 0

        for sname, sfunc in strategies:
            try:
                cnt = sfunc()
                if cnt > 0:
                    if best_strategy is None or cnt > best_count:
                        best_strategy = sname
                        best_count = cnt
            except:
                pass

        if best_count == 0:
            return {"error": f"未找到匹配文本（尝试验证了{len(strategies)}种策略）"}

        if best_count > 1 and not replace_all:
            return {"error": f"找到{best_count}处匹配（策略: {best_strategy}），请用更精确的文本或设置 replace_all=true"}

        # 执行替换
        bak_file = filepath + ".bak"
        shutil.copy2(filepath, bak_file)

        old_content = content

        if best_strategy == "精确匹配":
            if replace_all:
                content = content.replace(old_string, new_string)
            else:
                content = content.replace(old_string, new_string, 1)
        elif best_strategy == "忽略尾随空白":
            target = old_string.rstrip() + '\n'
            if replace_all:
                content = content.replace(target, new_string)
            else:
                content = content.replace(target, new_string, 1)
        elif best_strategy in ("忽略大小写", "行尾统一"):
            pattern = re.compile(re.escape(old_string), re.IGNORECASE)
            if replace_all:
                content = pattern.sub(new_string, content)
            else:
                content = pattern.sub(new_string, content, 1)
        elif best_strategy == "子串宽松":
            content = content.replace(old_string.strip(), new_string, 1)
        else:
            content = content.replace(old_string, new_string, 1)

        # 语法检查
        syntax_ok, syntax_msg = cls._check_syntax(filepath, content)
        if not syntax_ok:
            # 还原备份
            shutil.copy2(bak_file, filepath)
            return {"error": f"语法错误: {syntax_msg}", "backup": bak_file}

        with open(filepath, "w", encoding="utf-8") as f:
            f.write(content)

        diff = cls._make_diff(filepath, old_content, content)

        return {
            "ok": True,
            "matches": best_count,
            "strategy": best_strategy,
            "backup": bak_file,
            "diff": diff[:2000],
            "syntax_check": "passed" if syntax_ok else "skipped"
        }


# ========================================================================
# ExecuteCode —— 完整Python执行环境（隔离/超时/重试/循环）
# ========================================================================
class ExecuteCode:
    """安全Python代码执行器"""

    @staticmethod
    def execute(code, timeout=60, max_retries=2, workdir=None):
        """
        在子进程中执行Python代码
        - 隔离：独立进程，不污染主环境
        - 超时：默认60秒
        - 重试：失败自动重试（最多2次）
        - 返回：stdout/stderr/exit_code
        """
        last_error = ""

        for attempt in range(max_retries + 1):
            try:
                # 创建临时脚本
                fd, script_path = tempfile.mkstemp(suffix='.py', prefix='jl_exec_')
                with os.fdopen(fd, 'w', encoding='utf-8') as f:
                    f.write("#!/usr/bin/env python3\n")
                    f.write("# encoding: utf-8\n")
                    f.write("import sys, json, os, re, math, datetime, collections\n")
                    f.write("import subprocess, pathlib, hashlib, itertools\n\n")
                    f.write("try:\n")
                    f.write("    __stdout_backup = sys.stdout\n")
                    for line in code.split('\n'):
                        f.write(f"    {line}\n")
                    f.write("except Exception as e:\n")
                    f.write("    import traceback\n")
                    f.write("    print('ERROR:' + str(e), file=sys.stderr)\n")
                    f.write("    print('TRACEBACK:' + traceback.format_exc(), file=sys.stderr)\n")
                    f.write("    sys.exit(1)\n")

                env = os.environ.copy()
                cwd = workdir or os.getcwd()

                r = subprocess.run(
                    [sys.executable, script_path],
                    capture_output=True, text=True, timeout=timeout,
                    env=env, cwd=cwd
                )
            except subprocess.TimeoutExpired:
                last_error = f"超时（{timeout}s）"
                if attempt < max_retries:
                    time.sleep(1)
                continue
            except Exception as e:
                last_error = str(e)
                if attempt < max_retries:
                    time.sleep(1)
                continue
            finally:
                try: os.remove(script_path)
                except: pass

            # 成功返回
            return {
                "stdout": r.stdout[:5000],
                "stderr": r.stderr[:2000],
                "exit_code": r.returncode,
                "attempts": attempt + 1
            }

        return {"error": last_error, "attempts": max_retries + 1}


# ========================================================================
# CronScheduler —— 完整crontab调度器（真解析+每分钟检查+技能绑定）
# ========================================================================
class CronScheduler:
    """真正crontab语法定时任务调度器"""

    def __init__(self, data_dir, tools):
        self.data_dir = data_dir
        self.file = os.path.join(data_dir, "cron_jobs.json")
        self.local_copy = os.path.join(os.path.expanduser("~"), "src", ".cron_jobs_local.json")
        base_dir = os.path.dirname(data_dir) if os.path.basename(data_dir) == ".myagent" else data_dir
        self.default_feedback_root = os.path.join(base_dir, "cron_feedback")
        self.local_feedback_root = os.path.join(os.path.expanduser("~"), "src", "cron_feedback")
        self.run_log_file = os.path.join(data_dir, "cron_runs.jsonl")
        self.lock_dir = os.path.join(os.path.expanduser("~"), "src", ".cron_run_locks")
        self.tools = tools
        self.jobs = {}
        self._running = False
        self._thread = None
        self._lock = threading.RLock()
        self._load()

    def _safe_name(self, value, max_len=80):
        text = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(value or "").strip()).strip("_")
        return (text or "job")[:max_len]

    def _read_json_object(self, path):
        if not os.path.exists(path):
            return {}
        try:
            with open(path, encoding="utf-8") as f:
                return json.load(f)
        except json.JSONDecodeError:
            try:
                with open(path, encoding="utf-8") as f:
                    text = f.read()
                obj, idx = json.JSONDecoder().raw_decode(text)
                if isinstance(obj, dict):
                    try:
                        corrupt = f"{path}.corrupt.{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}"
                        shutil.copy2(path, corrupt)
                    except:
                        pass
                    return obj
            except:
                return {}
        except:
            return {}
        return {}

    def _load(self):
        cloud_jobs = self._read_json_object(self.file)
        local_jobs = self._read_json_object(self.local_copy)
        jobs = cloud_jobs if isinstance(cloud_jobs, dict) else {}
        if isinstance(local_jobs, dict):
            for name, local_info in local_jobs.items():
                if not isinstance(local_info, dict):
                    continue
                if name not in jobs:
                    jobs[name] = local_info
                    continue
                info = jobs.get(name) or {}
                if float(local_info.get("last_run", 0) or 0) > float(info.get("last_run", 0) or 0):
                    for key in ("last_run", "last_run_key", "last_status", "last_output_path", "last_error", "last_finished"):
                        if key in local_info:
                            info[key] = local_info.get(key)
                    jobs[name] = info
        self.jobs = jobs

    def _atomic_write_json(self, path, data):
        os.makedirs(os.path.dirname(path), exist_ok=True)
        tmp = f"{path}.tmp.{os.getpid()}.{uuid.uuid4().hex}"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
            f.write("\n")
        os.replace(tmp, path)

    def _save(self):
        with self._lock:
            try:
                self._atomic_write_json(self.file, self.jobs)
            except:
                pass
            # Keep a local mirror so background schedulers can read the queue reliably.
            try:
                self._atomic_write_json(self.local_copy, self.jobs)
            except:
                pass

    def parse_cron(self, expr):
        """完整解析crontab表达式"""
        parts = expr.strip().split()
        if len(parts) != 5: return None
        def _parse(p, lo, hi, names=None):
            def _atom(v):
                v = str(v).strip().lower()
                if names and v in names:
                    return names[v]
                return int(v)
            p = p.strip()
            if p == "*": return list(range(lo, hi+1))
            if "," in p:
                vals = []
                for part in p.split(","):
                    if "/" in part:
                        base, step = part.split("/")
                        step = int(step)
                        if "-" in base:
                            a, b = base.split("-", 1)
                            rng = range(_atom(a), _atom(b)+1)
                        else:
                            rng = range(lo, hi+1) if base == "*" else range(_atom(base), hi+1)
                        vals.extend(list(rng[::step]))
                    elif "-" in part:
                        a, b = part.split("-")
                        vals.extend(range(_atom(a), _atom(b)+1))
                    else:
                        vals.append(_atom(part))
                return sorted(set(vals))
            if "/" in p:
                base, step = p.split("/")
                step = int(step)
                if "-" in base:
                    a, b = base.split("-", 1)
                    rng = range(_atom(a), _atom(b)+1)
                else:
                    rng = range(lo, hi+1) if base == "*" else range(_atom(base), hi+1)
                return list(rng[::step])
            if "-" in p:
                a, b = p.split("-")
                return list(range(_atom(a), _atom(b)+1))
            return [_atom(p)]
        try:
            return {
                "minute": _parse(parts[0], 0, 59),
                "hour": _parse(parts[1], 0, 23),
                "day": _parse(parts[2], 1, 31),
                "month": _parse(parts[3], 1, 12),
                "weekday": _parse(parts[4], 0, 6, {"sun":0,"mon":1,"tue":2,"wed":3,"thu":4,"fri":5,"sat":6})
            }
        except: return None

    def should_run(self, parsed, dt=None):
        if not parsed: return False
        if dt is None: dt = datetime.datetime.now()
        if dt.minute not in parsed["minute"]: return False
        if dt.hour not in parsed["hour"]: return False
        if dt.day not in parsed["day"]: return False
        if dt.month not in parsed["month"]: return False
        cron_weekday = (dt.weekday() + 1) % 7  # cron: 0=Sunday, Python: 0=Monday
        if cron_weekday not in parsed["weekday"]: return False
        return True

    def add_job(self, name, cron_expr, task, prompt="", output_dir="", run_mode="", timeout_sec=1800, misfire_grace_minutes=10):
        parsed = self.parse_cron(cron_expr)
        if not parsed: return {"error": f"无效cron: {cron_expr}"}
        self.jobs[name] = {
            "cron": cron_expr, "task": task, "prompt": prompt,
            "parsed": {k:list(v) for k,v in parsed.items()},
            "created": time.time(), "last_run": 0, "enabled": True,
            "output_dir": output_dir or "",
            "run_mode": run_mode or "",
            "timeout_sec": int(timeout_sec or 1800),
            "misfire_grace_minutes": int(misfire_grace_minutes or 10)
        }
        self._save()
        return {"ok": True, "name": name, "cron": cron_expr, "next": self._next_run(parsed)}

    def remove_job(self, name):
        if name in self.jobs: del self.jobs[name]; self._save()
        return {"ok": True}

    def list_jobs(self):
        now = time.time(); res = []
        for n, i in self.jobs.items():
            last = i.get("last_run",0)
            ago = f"{(now-last)/60:.0f}m" if last else "never"
            p = i.get("parsed")
            next_run = self._next_run(p) if p else "?"
            res.append({
                "name": n, "cron": i.get("cron",""), "last_run": ago,
                "last_status": i.get("last_status", ""),
                "last_output_path": i.get("last_output_path", ""),
                "output_dir": i.get("output_dir", ""),
                "run_mode": i.get("run_mode", ""),
                "next": next_run, "enabled": i.get("enabled",True)
            })
        return res

    def _next_run(self, parsed):
        now = datetime.datetime.now()
        for m in range(1, 1441):
            check = now + datetime.timedelta(minutes=m)
            if self.should_run(parsed, check):
                return check.strftime("%Y-%m-%d %H:%M")
        return ">24h"

    def start_daemon(self):
        """启动每分钟检查的后台线程"""
        if self._running: return
        self._running = True
        def _loop():
            while self._running:
                try:
                    self._load()
                    now = datetime.datetime.now().replace(second=0, microsecond=0)
                    for name, info in list(self.jobs.items()):
                        if not info.get("enabled", True): continue
                        parsed = info.get("parsed")
                        if not parsed: continue
                        run_key = now.strftime("%Y-%m-%d %H:%M")
                        if info.get("last_run_key") == run_key: continue
                        if self.should_run(parsed, now):
                            self._execute_job(name, now)
                    # 睡到下一分钟开始
                    next_min = (now + datetime.timedelta(minutes=1)).replace(second=0, microsecond=0)
                    sleep_sec = (next_min - datetime.datetime.now()).total_seconds()
                    if sleep_sec > 0: time.sleep(min(sleep_sec, 60))
                except: time.sleep(60)
        self._thread = threading.Thread(target=_loop, daemon=True)
        self._thread.start()

    def _infer_run_mode(self, task, info=None):
        mode = ""
        if isinstance(info, dict):
            mode = str(info.get("run_mode") or info.get("mode") or "").strip().lower()
        if mode in ("shell", "agent"):
            return mode
        text = (task or "").strip()
        low = text.lower()
        shell_prefixes = ("python ", "python3 ", "bash ", "sh ", "zsh ", "cd ", "./", "/", "open ", "osascript ")
        if low.startswith(shell_prefixes) or "&&" in text or " | " in text or low.endswith(".py"):
            return "shell"
        return "agent"

    def _job_output_dir(self, name, info):
        raw = (info or {}).get("output_dir") or (info or {}).get("feedback_dir") or ""
        if raw:
            path = os.path.expandvars(os.path.expanduser(str(raw)))
            if not os.path.isabs(path):
                path = os.path.join(self.default_feedback_root, path)
        else:
            path = os.path.join(self.default_feedback_root, self._safe_name(name))
        try:
            os.makedirs(path, exist_ok=True)
            return path
        except:
            fallback = os.path.join(self.local_feedback_root, self._safe_name(name))
            os.makedirs(fallback, exist_ok=True)
            return fallback

    def _claim_run(self, name, run_key):
        os.makedirs(self.lock_dir, exist_ok=True)
        lock_name = self._safe_name(f"{name}_{run_key.replace(':','-').replace(' ','_')}", 120) + ".lock"
        lock_path = os.path.join(self.lock_dir, lock_name)
        try:
            fd = os.open(lock_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                f.write(json.dumps({"name": name, "run_key": run_key, "claimed_at": datetime.datetime.now().isoformat()}, ensure_ascii=False))
            return True
        except FileExistsError:
            return False
        except:
            return True

    def _popup_message(self, title, message, timeout_sec=8, open_path=None):
        """跨平台弹窗提醒，失败不影响定时任务结果。"""
        try:
            if os.environ.get("JL_CRON_POPUP", "").lower() in ("0", "false", "no"):
                return False
            title = str(title or "JL-Agent").replace("\r", " ").strip()[:120]
            message = str(message or "").replace("\r", " ").strip()[:900]
            open_path = self._clean_result_path(open_path or "")
            open_dir = open_path if open_path and os.path.isdir(open_path) else os.path.dirname(open_path)
            display_message = message
            if open_path:
                display_message = (message + "\n\n点“打开文件夹”查看结果。").strip()[:1100]
            timeout_sec = max(3, int(timeout_sec or 8))
            if sys.platform.startswith("win"):
                if open_path:
                    ps_script = (
                        "$title = @'\n" + title + "\n'@;\n"
                        "$msg = @'\n" + display_message + "\n'@;\n"
                        "$target = @'\n" + open_path + "\n'@;\n"
                        "$folder = @'\n" + open_dir + "\n'@;\n"
                        "$openResult = {\n"
                        "  if (Test-Path -LiteralPath $target -PathType Container) { Start-Process -FilePath $target }\n"
                        "  elseif (Test-Path -LiteralPath $target) { Start-Process -FilePath explorer.exe -ArgumentList ('/select,\"' + $target.Replace('\"','') + '\"') }\n"
                        "  elseif (Test-Path -LiteralPath $folder) { Start-Process -FilePath $folder }\n"
                        "};\n"
                        "try {\n"
                        "  Add-Type -AssemblyName System.Windows.Forms;\n"
                        "  Add-Type -AssemblyName System.Drawing;\n"
                        "  [System.Windows.Forms.Application]::EnableVisualStyles();\n"
                        "  $form = New-Object System.Windows.Forms.Form;\n"
                        "  $form.Text = $title; $form.StartPosition = 'CenterScreen'; $form.TopMost = $true;\n"
                        "  $form.Size = New-Object System.Drawing.Size(560,260); $form.MinimumSize = New-Object System.Drawing.Size(480,220);\n"
                        "  $box = New-Object System.Windows.Forms.TextBox;\n"
                        "  $box.Multiline = $true; $box.ReadOnly = $true; $box.ScrollBars = 'Vertical'; $box.BorderStyle = 'None';\n"
                        "  $box.BackColor = $form.BackColor; $box.Text = $msg; $box.Location = New-Object System.Drawing.Point(18,18); $box.Size = New-Object System.Drawing.Size(506,145);\n"
                        "  $btnOpen = New-Object System.Windows.Forms.Button; $btnOpen.Text = '打开文件夹'; $btnOpen.Size = New-Object System.Drawing.Size(110,32); $btnOpen.Location = New-Object System.Drawing.Point(292,178); $btnOpen.DialogResult = [System.Windows.Forms.DialogResult]::Yes;\n"
                        "  $btnClose = New-Object System.Windows.Forms.Button; $btnClose.Text = '关闭'; $btnClose.Size = New-Object System.Drawing.Size(90,32); $btnClose.Location = New-Object System.Drawing.Point(414,178); $btnClose.DialogResult = [System.Windows.Forms.DialogResult]::Cancel;\n"
                        "  $form.Controls.AddRange(@($box,$btnOpen,$btnClose)); $form.AcceptButton = $btnOpen; $form.CancelButton = $btnClose;\n"
                        "  $timer = New-Object System.Windows.Forms.Timer; $timer.Interval = " + str(timeout_sec * 1000) + "; $timer.Add_Tick({ $timer.Stop(); $form.DialogResult = [System.Windows.Forms.DialogResult]::Cancel; $form.Close() }); $timer.Start();\n"
                        "  $choice = $form.ShowDialog(); $timer.Stop(); $form.Dispose();\n"
                        "  if ($choice -eq [System.Windows.Forms.DialogResult]::Yes) { & $openResult }\n"
                        "} catch {\n"
                        "  $wshell = New-Object -ComObject WScript.Shell; $choice = $wshell.Popup($msg, " + str(timeout_sec) + ", $title, 68); if ($choice -eq 6) { & $openResult }\n"
                        "}\n"
                    )
                else:
                    ps_script = (
                        "$title = @'\n" + title + "\n'@;\n"
                        "$msg = @'\n" + message + "\n'@;\n"
                        "$wshell = New-Object -ComObject WScript.Shell;\n"
                        "$null = $wshell.Popup($msg, " + str(timeout_sec) + ", $title, 64);\n"
                    )
                subprocess.Popen(
                    ["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", ps_script],
                    stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL
                )
                return True
            if sys.platform == "darwin":
                if open_path:
                    script = (
                        "set targetPath to " + json.dumps(open_path, ensure_ascii=False) + "\n"
                        "set fallbackDir to " + json.dumps(open_dir, ensure_ascii=False) + "\n"
                        "set dlgResult to display dialog "
                        + json.dumps(display_message, ensure_ascii=False)
                        + ' buttons {"关闭", "打开文件夹"} default button "打开文件夹" giving up after '
                        + str(timeout_sec)
                        + " with title "
                        + json.dumps(title, ensure_ascii=False)
                        + "\n"
                        + 'if (gave up of dlgResult) is false and (button returned of dlgResult) is "打开文件夹" then\n'
                        + '  do shell script "if [ -d " & quoted form of targetPath & " ]; then open " & quoted form of targetPath & "; elif [ -e " & quoted form of targetPath & " ]; then open -R " & quoted form of targetPath & "; elif [ -d " & quoted form of fallbackDir & " ]; then open " & quoted form of fallbackDir & "; fi"\n'
                        + "end if"
                    )
                else:
                    script = (
                        "display dialog "
                        + json.dumps(message, ensure_ascii=False)
                        + ' buttons {"OK"} default button "OK" giving up after '
                        + str(timeout_sec)
                        + " with title "
                        + json.dumps(title, ensure_ascii=False)
                    )
                subprocess.Popen(["osascript", "-e", script], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                return True
        except:
            pass
        return False

    def _clean_result_path(self, value):
        text = str(value or "").strip()
        text = re.sub(r"^[✅✔\s]+", "", text)
        text = re.sub(r"\s+\(.+?\)\s*$", "", text)
        return text.strip(" \t\r\n\"'`，,;；。")

    def _extract_result_path(self, stdout, stderr, fallback):
        text = "\n".join([stdout or "", stderr or ""])
        label_pattern = re.compile(
            r"(?:文件|结果文件|输出文件|保存到|生成|导出)[：:]\s*"
            r"([A-Za-z]:\\[^\r\n]+|/[^\r\n]+)"
        )
        path_pattern = re.compile(
            r"([A-Za-z]:\\[^\r\n]+?\.(?:xlsx|xls|csv|txt|pdf|docx|pptx|json|html|md)|"
            r"/[^\r\n]+?\.(?:xlsx|xls|csv|txt|pdf|docx|pptx|json|html|md))",
            re.IGNORECASE,
        )
        for line in text.splitlines():
            match = label_pattern.search(line)
            if match:
                return self._clean_result_path(match.group(1))
        for line in text.splitlines():
            match = path_pattern.search(line)
            if match:
                return self._clean_result_path(match.group(1))
        return fallback

    def run_task_now(self, name, task, output_dir="", run_mode="", timeout_sec=1800, scheduled_for=None):
        scheduled_dt = scheduled_for or datetime.datetime.now().replace(second=0, microsecond=0)
        if isinstance(scheduled_dt, str):
            scheduled_text = scheduled_dt
            run_key = scheduled_dt[:16]
        else:
            scheduled_text = scheduled_dt.strftime("%Y-%m-%d %H:%M:%S")
            run_key = scheduled_dt.strftime("%Y-%m-%d %H:%M:%S")
        if not self._claim_run(name, run_key):
            return {"ok": False, "name": name, "skipped": "already_claimed", "run_key": run_key}
        info = {"task": task, "output_dir": output_dir or "", "run_mode": run_mode or "", "timeout_sec": int(timeout_sec or 1800)}
        self._queue_task(name, task, scheduled_text, info, run_key)
        thread = threading.Thread(target=self._run_job, args=(name, dict(info), scheduled_text, run_key), daemon=True)
        thread.start()
        return {"ok": True, "name": name, "run_key": run_key, "status": "started"}

    def _execute_job(self, name, scheduled_dt):
        info = self.jobs.get(name)
        if not info: return
        run_key = scheduled_dt.strftime("%Y-%m-%d %H:%M")
        if not self._claim_run(name, run_key):
            return
        info["last_run"] = time.time()
        info["last_run_key"] = run_key
        info["last_status"] = "running"
        self._save()
        task = info.get("task", "")
        now_str = scheduled_dt.strftime("%Y-%m-%d %H:%M:%S")
        print(f"\n  \033[38;2;255;215;0m[Cron]\033[0m {name}: {task[:100]}")
        try: self._queue_task(name, task, now_str, info, run_key)
        except: pass
        thread = threading.Thread(target=self._run_job, args=(name, dict(info), now_str, run_key), daemon=True)
        thread.start()

    def _run_job(self, name, info, scheduled_for, run_key):
        task = info.get("task", "")
        mode = self._infer_run_mode(task, info)
        timeout = int(info.get("timeout_sec") or 1800)
        out_dir = self._job_output_dir(name, info)
        ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        feedback_path = os.path.join(out_dir, f"{ts}_{self._safe_name(name)}.txt")
        env = os.environ.copy()
        env.update({
            "JL_CRON_JOB_NAME": name,
            "JL_CRON_RUN_KEY": run_key,
            "JL_CRON_SCHEDULED_FOR": scheduled_for,
            "JL_CRON_OUTPUT_DIR": out_dir,
            "JL_FEEDBACK_DIR": out_dir,
            "PYTHONIOENCODING": "utf-8"
        })
        started = datetime.datetime.now()
        status = "success"
        returncode = 0
        stdout = ""
        stderr = ""
        command_display = task
        try:
            if mode == "shell":
                kwargs = {"shell": True}
                if not sys.platform.startswith("win"):
                    kwargs["executable"] = "/bin/bash"
                result = subprocess.run(task, capture_output=True, text=True, timeout=timeout, env=env, **kwargs)
            else:
                agent_file = os.path.abspath(__file__)
                cmd = [sys.executable, agent_file, "--once", task]
                command_display = " ".join(cmd[:2]) + " --once " + task
                result = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, env=env, cwd=os.path.dirname(agent_file))
            returncode = result.returncode
            stdout = result.stdout or ""
            stderr = result.stderr or ""
            if returncode != 0:
                status = "failed"
        except subprocess.TimeoutExpired as e:
            status = "timeout"
            returncode = -1
            stdout = e.stdout or ""
            stderr = e.stderr or ""
            if isinstance(stdout, bytes):
                stdout = stdout.decode("utf-8", errors="replace")
            if isinstance(stderr, bytes):
                stderr = stderr.decode("utf-8", errors="replace")
            stderr += f"\n[TIMEOUT] 超过 {timeout} 秒"
        except Exception as e:
            status = "failed"
            returncode = -1
            stderr = str(e) + "\n" + traceback.format_exc()
        finished = datetime.datetime.now()
        elapsed = (finished - started).total_seconds()
        report = [
            "JL-Agent 定时任务反馈",
            f"任务: {name}",
            f"计划时间: {scheduled_for}",
            f"触发时间: {started.strftime('%Y-%m-%d %H:%M:%S')}",
            f"完成时间: {finished.strftime('%Y-%m-%d %H:%M:%S')}",
            f"耗时: {elapsed:.1f}s",
            f"状态: {status}",
            f"模式: {mode}",
            f"反馈目录: {out_dir}",
            "",
            "任务内容:",
            task,
            "",
            "执行命令:",
            command_display,
            "",
            "--- STDOUT ---",
            stdout[-20000:],
            "",
            "--- STDERR ---",
            stderr[-10000:],
            ""
        ]
        try:
            with open(feedback_path, "w", encoding="utf-8") as f:
                f.write("\n".join(report))
            latest_path = os.path.join(out_dir, "latest.txt")
            shutil.copy2(feedback_path, latest_path)
        except:
            feedback_path = ""
        result_path = self._extract_result_path(stdout, stderr, feedback_path or os.path.join(out_dir, "latest.txt"))
        popup_title = "JL-Agent 定时任务完成" if status == "success" else "JL-Agent 定时任务失败"
        popup_body = "\n".join([
            f"{name}: {status}",
            f"完成时间: {finished.strftime('%Y-%m-%d %H:%M:%S')}",
            f"文件: {result_path}",
        ])
        self._popup_message(popup_title, popup_body, timeout_sec=30, open_path=result_path)
        run_meta = {
            "name": name, "run_key": run_key, "scheduled_for": scheduled_for,
            "started": started.isoformat(), "finished": finished.isoformat(),
            "elapsed_sec": elapsed, "status": status, "returncode": returncode,
            "mode": mode, "output_path": feedback_path
        }
        try:
            os.makedirs(os.path.dirname(self.run_log_file), exist_ok=True)
            with open(self.run_log_file, "a", encoding="utf-8") as f:
                f.write(json.dumps(run_meta, ensure_ascii=False) + "\n")
        except:
            pass
        with self._lock:
            current = self.jobs.get(name)
            if isinstance(current, dict):
                current["last_status"] = status
                current["last_output_path"] = feedback_path
                current["last_error"] = stderr[-500:] if status != "success" else ""
                current["last_finished"] = finished.isoformat()
                current["last_run"] = time.time()
                current["last_run_key"] = run_key
                self._save()

    def _queue_task(self, name, task, triggered_at, info=None, run_key=""):
        """定时任务写入待办队列"""
        entry = {
            "name": name, "task": task, "triggered_at": triggered_at,
            "run_key": run_key, "output_dir": (info or {}).get("output_dir", "")
        }
        data_dir = globals().get("PERSONAL_DATA_DIR") or os.path.join(os.path.expanduser("~"), ".jl-agent")
        queue_files = [
            os.path.join(data_dir, ".cron_queue.jsonl"),
            os.path.join(tempfile.gettempdir(), "jl-agent-cron-queue.jsonl")
        ]
        for queue_file in queue_files:
            try:
                os.makedirs(os.path.dirname(queue_file), exist_ok=True)
                with open(queue_file, "a", encoding="utf-8") as f:
                    f.write(json.dumps(entry, ensure_ascii=False) + "\n")
            except:
                pass

    def stop(self):
        self._running = False


# ========================================================================
# inject_tools —— 注册所有工具到 Tools 对象
# ========================================================================
def inject_tools(tools_obj, memory, api_url, api_key, model, data_dir, skills_dir):
    """注入15个Hermes级工具到Tools对象"""

    # ---------- 精确patch ----------
    def tool_exact_patch(filepath, old_string, new_string, replace_all=False):
        return ExactPatch.patch(filepath, old_string, new_string, replace_all)

    # ---------- execute_code ----------
    def tool_execute_code(code, timeout=60, retry=True, workdir=None):
        max_retries = 2 if retry else 0
        return ExecuteCode.execute(code, timeout, max_retries, workdir)

    # ---------- patch_skill（增强版）----------
    def tool_patch_skill(name, old_text, new_text):
        fp = os.path.join(skills_dir, f"{name}.md")
        if not os.path.exists(fp): return {"error": f"技能 {name} 不存在"}
        result = ExactPatch.patch(fp, old_text, new_text)
        if "error" in result: return result
        with open(fp, encoding="utf-8") as f: tools_obj.loaded_skills[name] = f.read()
        return result

    # ---------- 其余工具（保持原样）----------
    def tool_delete_skill(name):
        fp = os.path.join(skills_dir, f"{name}.md")
        if not os.path.exists(fp): return {"error": "不存在"}
        os.remove(fp); tools_obj.loaded_skills.pop(name, None)
        return {"ok": True}

    def tool_load_all_skills():
        cnt = 0
        for fn in os.listdir(skills_dir):
            if fn.endswith(".md"):
                with open(os.path.join(skills_dir, fn), encoding="utf-8") as f:
                    tools_obj.loaded_skills[fn[:-3]] = f.read(); cnt += 1
        return {"loaded": cnt}

    def tool_search_all_sessions(keyword):
        if hasattr(tools_obj, 'sessions') and tools_obj.sessions:
            r = tools_obj.sessions.search(keyword)
            return {"results": r, "total": len(r)}
        return {"error": "会话存储未启用"}

    def tool_delegate_task(goal, context=""):
        tid = uuid.uuid4().hex[:8]
        spath = os.path.join(data_dir, f"subagent_{tid}.py")
        prompt_escaped = (goal + "\n" + context[:800]).replace('"', '\\"')
        script = f'''#!/usr/bin/env python3
import sys, json, requests, os
API_URL = os.environ.get("HERMES_API_URL", "{api_url.replace(chr(34), '')}")
API_KEY = os.environ.get("HERMES_API_KEY", "{api_key.replace(chr(34), '')}")
MODEL = os.environ.get("HERMES_MODEL", "{model.replace(chr(34), '')}")
p = """{prompt_escaped}"""
try:
    r = requests.post(API_URL, json={{"model": MODEL, "messages": [{{"role": "system", "content": "子Agent. 专注目标直接回答."}}, {{"role": "user", "content": p}}], "temperature": 0.3, "max_tokens": 2000}}, headers={{"Authorization": f"Bearer {{API_KEY}}"}} if API_KEY else {{}}, timeout=120)
    result = r.json()["choices"][0]["message"]["content"]
except Exception as e: result = "错误: " + str(e)
print(json.dumps({{"task_id": "{tid}", "result": result}}, ensure_ascii=False))
'''
        with open(spath, "w", encoding="utf-8") as f: f.write(script)
        try:
            env = os.environ.copy()
            env["HERMES_API_URL"] = api_url
            env["HERMES_API_KEY"] = api_key
            env["HERMES_MODEL"] = model
            r = subprocess.run([sys.executable, spath], capture_output=True, text=True, timeout=300, env=env)
            os.remove(spath)
            if r.returncode == 0:
                try: return json.loads(r.stdout)
                except: return {"task_id": tid, "result": r.stdout[:2000]}
            return {"error": "子Agent失败", "stderr": r.stderr[:500]}
        except subprocess.TimeoutExpired: return {"error": "子Agent超时"}
        except Exception as e: return {"error": str(e)}

    def tool_cron_create(name, cron_expr, task, output_dir="", run_mode="", timeout_sec=1800, misfire_grace_minutes=10):
        if hasattr(tools_obj, 'cron') and tools_obj.cron:
            return tools_obj.cron.add_job(
                name, cron_expr, task,
                output_dir=output_dir or "",
                run_mode=run_mode or "",
                timeout_sec=timeout_sec or 1800,
                misfire_grace_minutes=misfire_grace_minutes or 10
            )
        return {"error": "Cron未启用"}

    def tool_cron_list():
        if hasattr(tools_obj, 'cron') and tools_obj.cron: return {"jobs": tools_obj.cron.list_jobs()}
        return {"error": "Cron未启用"}

    def tool_cron_remove(name):
        if hasattr(tools_obj, 'cron') and tools_obj.cron: return tools_obj.cron.remove_job(name)
        return {"error": "Cron未启用"}

    def tool_cron_start():
        if hasattr(tools_obj, 'cron') and tools_obj.cron:
            tools_obj.cron.start_daemon()
            return {"ok": True, "message": "Cron守护线程已启动"}
        return {"error": "Cron未启用"}

    def tool_process_list():
        try:
            if sys.platform.startswith('win'): r = subprocess.run("tasklist", shell=True, capture_output=True, text=True, timeout=10)
            else: r = subprocess.run(["ps", "aux", "--sort=-%mem"], capture_output=True, text=True, timeout=10)
            return {"processes": r.stdout[:2000]}
        except Exception as e: return {"error": str(e)}

    def tool_process_kill(pid):
        try:
            if sys.platform.startswith('win'): subprocess.run(f"taskkill /F /PID {pid}", shell=True, timeout=10)
            else: os.kill(pid, 9)
            return {"ok": True}
        except Exception as e: return {"error": str(e)}

    def tool_memory_delete(key):
        memory.delete(key)
        return {"ok": True}

    def tool_session_stats():
        if hasattr(tools_obj, 'sessions') and tools_obj.sessions: return tools_obj.sessions.get_stats()
        return {"sessions": 0}

    # Register
    tools_obj.tool_exact_patch = tool_exact_patch
    tools_obj.tool_execute_code = tool_execute_code
    tools_obj.tool_patch_skill = tool_patch_skill
    tools_obj.tool_delete_skill = tool_delete_skill
    tools_obj.tool_load_all_skills = tool_load_all_skills
    tools_obj.tool_search_all_sessions = tool_search_all_sessions
    tools_obj.tool_delegate_task = tool_delegate_task
    tools_obj.tool_cron_create = tool_cron_create
    tools_obj.tool_cron_list = tool_cron_list
    tools_obj.tool_cron_remove = tool_cron_remove
    tools_obj.tool_cron_start = tool_cron_start
    tools_obj.tool_process_list = tool_process_list
    tools_obj.tool_process_kill = tool_process_kill
    tools_obj.tool_memory_delete = tool_memory_delete
    tools_obj.tool_session_stats = tool_session_stats
    # --- 新增最终版工具 ---
    tools_obj.model_router = ModelRouter()
    tools_obj.model_router.configure(MODEL, API_URL, API_KEY or "",
        {"vba": MODEL, "python": MODEL, "quick": MODEL, "reasoning": MODEL})

    def tool_process_wait(pid, timeout=30):
        try:
            import time as _t
            for _ in range(timeout):
                if sys.platform.startswith('win'):
                    r = subprocess.run(f"tasklist /FI \"PID eq {pid}\"", shell=True, capture_output=True, text=True, timeout=5)
                    if str(pid) not in r.stdout: return {"exited": True}
                else:
                    try: os.kill(pid, 0)
                    except: return {"exited": True}
                _t.sleep(1)
            return {"exited": False, "timeout": timeout}
        except Exception as e: return {"error": str(e)}

    def tool_process_poll(pid):
        try:
            if sys.platform.startswith('win'):
                r = subprocess.run(f"tasklist /FI \"PID eq {pid}\"", shell=True, capture_output=True, text=True, timeout=5)
                return {"running": str(pid) in r.stdout}
            else:
                os.kill(pid, 0); return {"running": True}
        except: return {"running": False}

    def tool_set_model(task_type, model_name):
        if hasattr(tools_obj, 'model_router'):
            tools_obj.model_router.set_for_task(task_type, model_name)
            return {"ok": True, "task_type": task_type, "model": model_name}
        return {"error": "router not available"}

    def tool_list_models():
        if hasattr(tools_obj, 'model_router'):
            return tools_obj.model_router.list()
        return {"error": "router not available"}

    tools_obj.tool_process_wait = tool_process_wait
    tools_obj.tool_process_poll = tool_process_poll
    tools_obj.tool_set_model = tool_set_model
    tools_obj.tool_list_models = tool_list_models
    return True

