def inject_initial_experience(memory):
    """注入真实对话经验到持久记忆（仅首次运行）"""
    key = "_initial_experience_seeded"
    mems = memory.load_all()
    if key in mems:
        return  # 已经种过，跳过

    memory.save(key, "true")
    print("  [Experience] 已注入初始经验")



