# ====== extract function ======
def _extract_skills(data_dir):
    sd = os.path.join(data_dir, "skills")
    if os.path.exists(sd) and len(os.listdir(sd)) > 5: return
    os.makedirs(sd, exist_ok=True)
    import tarfile, io
    try:
        raw = base64.b64decode(SKILLS_ARCHIVE_B64)
        with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as tar:
            for m in tar.getmembers():
                if m.name.endswith("SKILL.md"):
                    p = m.name.split("/")
                    if len(p) >= 2:
                        m.name = f"{p[-2]}.md"
                        tar.extract(m, path=sd)
                elif m.name.endswith(".md") and "/" not in m.name and m.name != "_INDEX.md":
                    tar.extract(m, path=sd)
    except Exception as e:
        print(f"! extract failed: {e}")
    cnt = len([f for f in os.listdir(sd) if f.endswith(".md")])
    print(f"Extracted {cnt} skills")

# ====== JL-Agent ======
#!/usr/bin/env python3
"""
JL-Agent — 运行在本地的 AI 助手
用法：
  python3 my_agent.py
配置文件在脚本同目录下 myagent_config.json（启动时自动创建）
"""
import requests, json, subprocess, sqlite3, os, re, sys, datetime
# hermes_enhance inlined
import urllib.parse, pathlib, textwrap, base64, time, platform, traceback, shutil, threading

# Rich 库检测（有则用，无则回退到 ANSI）
try:
    from rich.console import Console as _RichConsole
    from rich.panel import Panel as _RichPanel
    from rich import box as _RichBox
    _HAS_RICH = True
except ImportError:
    _HAS_RICH = False

# prompt_toolkit 检测（用于输入框，完美支持中文）
try:
    from prompt_toolkit import prompt as _pt_prompt
    from prompt_toolkit.formatted_text import ANSI as _PT_ANSI
    from prompt_toolkit.completion import Completer as _PT_C, Completion as _PT_CM
    _SLASH_LIST = [
        ("/exit", "退出"),
        ("/new", "重置当前会话"),
        ("/version", "查看版本"),
        ("/cfg", "查看配置文件"),
        ("/config_path", "查看配置文件路径"),
        ("/init_config", "初始化/补齐配置文件"),
        ("/reload_config", "重新加载API配置"),
        ("/selfcheck", "运行环境自检"),
        ("/releasecheck", "运行GitHub发布自检"),
        ("/project", "扫描工程项目"),
        ("/changes", "查看工作树变更"),
        ("/verify", "给出验证命令建议"),
        ("/plan", "查看/维护任务计划"),
        ("/runverify", "运行验证流水线"),
        ("/gitdiff", "查看Git diff"),
        ("/audit", "查看工具审计日志"),
        ("/admin", "用户管理"),
        ("/admin list", "列出所有注册用户"),
        ("/admin allow ", "授权维护权限"),
        ("/admin block ", "收回维护权限"),
        ("/admin promote ", "提升为管理员"),
        ("/admin pro ", "提升为管理员（别名）"),
        ("/admin demote ", "取消管理员"),
        ("/admin depro ", "取消管理员（别名）"),
        ("/summary", "查看今日会话摘要（仅管理员）"),
        ("/导出", "导出当前知识库到 txt"),
        ("/dash", "打开 Web 管理后台（别名）"),
        ("/dashboard", "打开 Web 管理后台"),
        ("/setup", "导入 Hermes 技能"),
        ("/cron", "查看定时任务"),
        ("/stock", "查看A股投研日报"),
        ("/stock run", "手动运行A股投研日报"),
        ("/stock install", "安装A股投研cron"),
        ("/stats", "会话统计"),
        ("/skills", "列出所有技能"),
        ("/help", "显示帮助"),
        ("/h", "显示帮助"),
    ]
    class _SlashCompleter(_PT_C):
        def get_completions(self, document, complete_event):
            text = document.text_before_cursor
            if text.startswith("/"):
                for cmd, desc in _SLASH_LIST:
                    if cmd.startswith(text):
                        yield _PT_CM(cmd, start_position=-len(text), display_meta=desc)
    _SLASH_CMDS = _SlashCompleter()
    _HAS_PT = True
except:
    _HAS_PT = False

# ====== 平台检测 ======
IS_WINDOWS = platform.system() == "Windows"
if IS_WINDOWS:
    for _stream_name in ("stdout", "stderr"):
        try:
            getattr(sys, _stream_name).reconfigure(encoding="utf-8", errors="replace")
        except:
            pass

# Optional external skills source. The embedded skills are available without this path.
HERMES_SKILLS_PATH = os.path.abspath(os.path.expanduser(os.path.expandvars(
    os.environ.get("JL_AGENT_SKILLS_SOURCE", os.path.join(os.path.expanduser("~"), "JL-Agent", "skills-source"))
)))

SHELL_CMD = "cmd /c" if IS_WINDOWS else ""

def _safe_makedirs(path):
    if not path:
        return None
    try:
        full = os.path.abspath(os.path.expandvars(os.path.expanduser(path)))
        os.makedirs(full, exist_ok=True)
        return full
    except Exception:
        return None

def _default_user_data_dir():
    if IS_WINDOWS:
        base = (
            os.environ.get("LOCALAPPDATA")
            or os.environ.get("USERPROFILE")
            or tempfile.gettempdir()
        )
        return os.path.join(base, "JL-Agent")
    if sys.platform == "darwin":
        return os.path.join(os.path.expanduser("~/Library/Application Support"), "JL-Agent")
    base = (
        os.environ.get("XDG_DATA_HOME")
        or os.path.expanduser("~/.local/share")
        or tempfile.gettempdir()
    )
    return os.path.join(base, "JL-Agent")

def _resolve_storage_dirs():
    """Resolve configurable personal/shared storage directories on all platforms."""
    override = os.environ.get("JL_AGENT_HOME", "").strip()
    if override:
        base = _safe_makedirs(override)
        if base:
            return base, base
    personal_raw = os.environ.get("JL_AGENT_PERSONAL_DIR", "").strip()
    share_raw = os.environ.get("JL_AGENT_SHARE_DIR", "").strip()
    personal_dir = _safe_makedirs(personal_raw) if personal_raw else None
    personal_dir = personal_dir or _safe_makedirs(_default_user_data_dir()) or tempfile.gettempdir()
    if share_raw:
        share_dir = _safe_makedirs(share_raw)
        if share_dir:
            return personal_dir, share_dir
    return personal_dir, personal_dir

# ====== 配置（改这里就行，第一次运行自动生成 myagent_config.json）======
# Packaged deployments can change API settings in the generated JSON config without rebuilding.
API_URL = os.environ.get("JL_AGENT_API_URL", "https://api.deepseek.com/v1/chat/completions")
API_KEY = os.environ.get("JL_AGENT_API_KEY", "")
MODEL = os.environ.get("JL_AGENT_MODEL", "deepseek-v4-pro")
# ==== 高级配置 ====
MAX_TURNS = 100
MAX_CONTEXT_CHARS = 64000
RECENT_CHATS_N = 5
MEMORY_DIR = ".myagent"

# 静默模式：只显示最终结果，不显示中间工具调用过程
# 启动时加 --quiet 或设置环境变量 JL_QUIET=1
QUIET_MODE = False

PERSONAL_DIR, SHARE_DIR = _resolve_storage_dirs()
if sys.platform.startswith("win"):
    # 启用 CMD ANSI/VT 支持（Win10 1607+），让 Rich 面板正常渲染
    try:
        import ctypes as _ct
        _k32 = _ct.windll.kernel32
        for _h in (_k32.GetStdHandle(-11), _k32.GetStdHandle(-12)):
            _m = _ct.c_uint32()
            if _k32.GetConsoleMode(_h, _ct.byref(_m)):
                _k32.SetConsoleMode(_h, _m.value | 0x0004)
    except:
        pass
    os.makedirs(PERSONAL_DIR, exist_ok=True)
