# ====== Emoji兼容（Windows CMD缺字体时替换为纯文本）======
_EMOJI_MAP = {
    "✅": "[OK]", "❌": "[X]", "⚠️": "[!]", "🔴": "[!!]", "🟢": "[OK]",
    "⭐": "*", "⚪": "-", "📝": "[写]", "🔧": "[修]", "🌐": "[网]", "📡": "[抓]",
    "🔍": "[搜]", "📂": "[目]", "💾": "[存]", "🔎": "[找]", "📋": "[录]",
    "📦": "[技]", "🧠": "[学]", "🖼️": "[图]", "⚡": "[~]", "🐍": "[Py]",
    "📖": "[读]", "$": "$",
}
def _e(s, force_ascii=None):
    """Windows CMD 没有emoji字体时，替换为纯文本标记"""
    if force_ascii is None:
        force_ascii = sys.platform.startswith("win")
    if not force_ascii:
        return s
    for emoji, text in _EMOJI_MAP.items():
        s = s.replace(emoji, text)
    return s

def _stream_print_text(text, delay=0.009):
    """终端里做近似 token 流式显示。"""
    if text is None:
        text = ""
    for ch in str(text):
        sys.stdout.write(ch)
        sys.stdout.flush()
        if ch not in ("\r",):
            time.sleep(delay if ch not in ("\n", " ", "\t") else min(0.003, delay))

def _candidate_workspace_roots():
    roots = []
    try:
        roots.append(os.path.dirname(os.path.abspath(__file__)))
    except:
        pass
    for p in [
        SHARE_DATA_DIR if 'SHARE_DATA_DIR' in globals() else "",
        PERSONAL_DATA_DIR if 'PERSONAL_DATA_DIR' in globals() else "",
        os.environ.get("JL_AGENT_WORKSPACE_ROOT", ""),
        os.path.expanduser("~/JL-Agent"),
        os.path.expanduser("~/Projects"),
    ]:
        if p and os.path.exists(p):
            roots.append(os.path.abspath(p))
    out = []
    seen = set()
    for p in roots:
        ap = os.path.abspath(p)
        if ap not in seen:
            seen.add(ap)
            out.append(ap)
    return out

def resolve_user_path(path_value, must_exist=False):
    raw = str(path_value or "").strip()
    if not raw:
        candidate = os.path.abspath(".")
        return candidate if (not must_exist or os.path.exists(candidate)) else candidate

    norm = raw.replace("\\", "/")
    workspace_roots = _candidate_workspace_roots()
    aliases = []
    if workspace_roots:
        aliases.extend([
            "workspace",
            "./workspace",
            "project",
            "./project",
        ])
    candidates = []

    alias_matched = False
    for alias in aliases:
        if norm == alias or norm.startswith(alias + "/"):
            alias_matched = True
            suffix = norm[len(alias):].lstrip("/")
            for root in workspace_roots:
                candidates.append(os.path.join(root, suffix) if suffix else root)

    if os.path.isabs(raw):
        candidates.append(raw)
    expanded = os.path.expanduser(raw)
    if not alias_matched:
        candidates.append(expanded)

    if not os.path.isabs(expanded):
        for root in workspace_roots:
            candidates.append(os.path.join(root, raw))
        candidates.append(os.path.join(os.path.expanduser("~"), raw))
        candidates.append(os.path.abspath(expanded))

    seen = set()
    ordered = []
    for cand in candidates:
        ap = os.path.abspath(os.path.expanduser(cand))
        if ap not in seen:
            seen.add(ap)
            ordered.append(ap)
    if must_exist:
        for cand in ordered:
            if os.path.exists(cand):
                return cand
    return ordered[0] if ordered else os.path.abspath(os.path.expanduser(raw))

# ====== 用户管理与权限系统 ======
USERS_FILE = os.path.join(SHARE_DIR, "users.json") if IS_WINDOWS else os.path.join(DATA_DIR, "users.json")

def get_user_identity():
    """返回当前用户唯一标识: 用户名@主机名"""
    if IS_WINDOWS:
        user = os.environ.get("USERNAME", "unknown")
        host = os.environ.get("COMPUTERNAME", "unknown")
    else:
        user = os.environ.get("USER", "unknown")
        host = platform.node() or "unknown"
    return f"{user}@{host}"

def load_users():
    """加载用户注册表，返回 dict"""
    if not os.path.exists(USERS_FILE):
        return {"admins": [], "users": {}, "learn_whitelist": [], "created_at": None}
    try:
        with open(USERS_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
    except:
        return {"admins": [], "users": {}, "learn_whitelist": [], "created_at": None}
    if "users" not in data or not isinstance(data.get("users"), dict):
        data["users"] = {}
    if "learn_whitelist" not in data or not isinstance(data.get("learn_whitelist"), list):
        data["learn_whitelist"] = []
    if "admins" not in data:
        old_admin = data.pop("admin", None)
        data["admins"] = [old_admin] if old_admin else []
    data["admins"] = [u for u in data.get("admins", []) if u]
    return data

def save_users(data):
    """安全保存用户注册表（临时文件+原子替换）"""
    os.makedirs(os.path.dirname(USERS_FILE), exist_ok=True)
    tmp = USERS_FILE + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    try:
        os.replace(tmp, USERS_FILE)
    except:
        shutil.move(tmp, USERS_FILE)

def register_current_user():
    """注册当前用户。首次注册自动成为管理员。"""
    global IS_FIRST_USER, USERS_ADMINS, USER_ID
    uid = get_user_identity()
    USER_ID = uid
    data = load_users()
    now = datetime.datetime.now().isoformat()
    is_new = uid not in data["users"]
    if is_new:
        data["users"][uid] = {
            "registered_at": now,
            "display_name": uid,
            "can_learn": False
        }
    if not data["admins"]:
        data["admins"] = [uid]
        data["users"][uid]["can_learn"] = True
        if uid not in data["learn_whitelist"]:
            data["learn_whitelist"].append(uid)
        IS_FIRST_USER = True
    if not data.get("created_at"):
        data["created_at"] = now
    USERS_ADMINS = data["admins"]
    save_users(data)
    return data, uid, is_new

def is_admin():
    return USERS_ADMINS and get_user_identity() in USERS_ADMINS

def can_learn():
    uid = get_user_identity()
    data = load_users()
    return uid in data.get("learn_whitelist", [])

DEV_TOOL_NAMES = {
    "execute_command", "write_file", "patch_file", "load_skill", "learn_skill",
    "python_execute", "patch_skill", "delete_skill", "load_all_skills",
    "delegate_task", "process_kill", "exact_patch", "execute_code",
    "cron_start", "set_model", "project_scan", "worktree_status",
    "verify_suggestions", "task_plan", "preview_patch", "git_diff",
    "run_verification", "stock_market_run_daily", "stock_market_install_cron"
}

ADMIN_ONLY_TOOL_NAMES = {
    "search_all_sessions", "process_list", "process_wait", "process_poll",
    "list_models", "audit_log"
}

def get_user_role(user_id=None, data=None):
    uid = user_id or get_user_identity()
    data = data or load_users()
    admins = set(data.get("admins", []))
    learners = set(data.get("learn_whitelist", []))
    if uid in admins:
        return "admin"
    if uid in learners:
        return "maintainer"
    return "viewer"

def get_allowed_tool_names(user_id=None, data=None):
    role = get_user_role(user_id=user_id, data=data)
    all_names = {t["function"]["name"] for t in TOOLS if t.get("function", {}).get("name")}
    if role == "admin":
        return all_names
    allowed = all_names - DEV_TOOL_NAMES - ADMIN_ONLY_TOOL_NAMES - {"learn"}
    if role == "maintainer":
        allowed.add("learn")
    return allowed

def tool_is_allowed(name, user_id=None, data=None):
    return name in get_allowed_tool_names(user_id=user_id, data=data)

def tool_permission_message(name, user_id=None, data=None):
    role = get_user_role(user_id=user_id, data=data)
    if name == "learn":
        return "你没有知识库投喂权限。请联系管理员授权后再导入业务资料。"
    if role == "admin":
        return ""
    if role == "maintainer":
        return "维护员只能处理非开发任务和知识库投喂；开发、改代码、执行命令、改技能这类事情仅管理员可用。"
    return "普通用户不能让 agent 做开发相关工作；只允许非开发类任务。需要开发能力请让管理员操作。"

def filter_tools_for_user(user_id=None, data=None):
    allowed = get_allowed_tool_names(user_id=user_id, data=data)
    return [t for t in TOOLS if t.get("function", {}).get("name") in allowed]

def build_role_policy_prompt(user_id=None, data=None):
    role = get_user_role(user_id=user_id, data=data)
