def _extract_plain_text(content):
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for item in content:
            if isinstance(item, dict):
                if item.get("type") == "text":
                    parts.append(str(item.get("text", "")))
                elif item.get("type") == "image_url":
                    parts.append(str(item.get("image_url", {}).get("url", "")))
            elif item:
                parts.append(str(item))
        return " ".join(parts)
    return str(content or "")

def looks_like_development_request(content):
    text = _extract_plain_text(content).lower().strip()
    if not text or text.startswith("/"):
        return False
    dev_keywords = [
        "代码", "脚本", "开发", "编程", "程序", "调试", "bug", "报错修复", "修bug",
        "改代码", "写代码", "补丁", "patch", "commit", "git", "接口开发", "前端",
        "后端", "vba", "python", "javascript", "js", "typescript", "ts", "sql",
        ".py", ".js", ".ts", ".sql", "agent开发", "技能开发", "执行命令", "跑命令"
    ]
    dev_patterns = [
        r"写.*脚本", r"写.*代码", r"改.*代码", r"修.*代码", r"开发.*功能", r"做.*开发",
        r"生成.*代码", r"帮我.*编程", r"帮我.*debug", r"批量.*改代码"
    ]
    if any(k in text for k in dev_keywords):
        return True
    return any(re.search(p, text) for p in dev_patterns)

