ONLINE_FILE = os.path.join(SHARE_DATA_DIR, "online.json")
SCHEDULED_FILE = os.path.join(PERSONAL_DATA_DIR, "scheduled.json")
_ONLINE_LOCK = threading.Lock()

def _heartbeat():
    """更新在线心跳"""
    try:
        with _ONLINE_LOCK:
            now = time.time()
            online = {}
            if os.path.exists(ONLINE_FILE):
                try:
                    with open(ONLINE_FILE, encoding="utf-8") as f:
                        online = json.load(f)
                except:
                    online = {}
            online[get_user_identity()] = now
            for k in list(online.keys()):
                if now - online[k] > 86400:
                    del online[k]
            os.makedirs(os.path.dirname(ONLINE_FILE), exist_ok=True)
            tmp = ONLINE_FILE + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(online, f, ensure_ascii=False, indent=2)
            os.replace(tmp, ONLINE_FILE)
    except: pass

