def _default_runtime_config():
    return {
        "api": {
            "url": os.environ.get("JL_AGENT_API_URL", API_URL),
            "key": os.environ.get("JL_AGENT_API_KEY", API_KEY),
            "model": os.environ.get("JL_AGENT_MODEL", MODEL)
        },
        "agent": {
            "max_turns": MAX_TURNS,
            "max_context_chars": MAX_CONTEXT_CHARS,
            "recent_chats_to_inject": RECENT_CHATS_N
        },
        "memory": {"db_dir": MEMORY_DIR},
        "stock_research": {
            "dir": os.environ.get("JL_AGENT_STOCK_RESEARCH_DIR", ""),
            "python": os.environ.get("JL_AGENT_STOCK_RESEARCH_PYTHON", ""),
            "cron": os.environ.get("JL_AGENT_STOCK_RESEARCH_CRON", "30 15 * * 1-5"),
            "job_name": os.environ.get("JL_AGENT_STOCK_RESEARCH_JOB", "A股投研日报")
        },
        "payment": {
            "wechat_qr": os.environ.get("JL_AGENT_WECHAT_QR", "payment/wechat_qr.png"),
            "wechat_name": os.environ.get("JL_AGENT_WECHAT_NAME", "WeChat Pay"),
            "note": os.environ.get("JL_AGENT_PAYMENT_NOTE", "Confirm the plan, then scan with WeChat Pay.")
        }
    }

def _merge_runtime_config(raw):
    cfg = _default_runtime_config()
    if isinstance(raw, dict):
        for section in ("api", "agent", "memory", "stock_research", "payment"):
            if isinstance(raw.get(section), dict):
                cfg[section].update(raw.get(section) or {})
    # 环境变量优先，方便公司内网批量部署时用启动脚本覆盖。
    if os.environ.get("JL_AGENT_API_URL"):
        cfg["api"]["url"] = os.environ["JL_AGENT_API_URL"]
    if os.environ.get("JL_AGENT_API_KEY"):
        cfg["api"]["key"] = os.environ["JL_AGENT_API_KEY"]
    if os.environ.get("JL_AGENT_MODEL"):
        cfg["api"]["model"] = os.environ["JL_AGENT_MODEL"]
    if os.environ.get("JL_AGENT_STOCK_RESEARCH_DIR"):
        cfg.setdefault("stock_research", {})["dir"] = os.environ["JL_AGENT_STOCK_RESEARCH_DIR"]
    if os.environ.get("JL_AGENT_STOCK_RESEARCH_PYTHON"):
        cfg.setdefault("stock_research", {})["python"] = os.environ["JL_AGENT_STOCK_RESEARCH_PYTHON"]
    if os.environ.get("JL_AGENT_STOCK_RESEARCH_CRON"):
        cfg.setdefault("stock_research", {})["cron"] = os.environ["JL_AGENT_STOCK_RESEARCH_CRON"]
    if os.environ.get("JL_AGENT_STOCK_RESEARCH_JOB"):
        cfg.setdefault("stock_research", {})["job_name"] = os.environ["JL_AGENT_STOCK_RESEARCH_JOB"]
    if os.environ.get("JL_AGENT_WECHAT_QR"):
        cfg.setdefault("payment", {})["wechat_qr"] = os.environ["JL_AGENT_WECHAT_QR"]
    if os.environ.get("JL_AGENT_WECHAT_NAME"):
        cfg.setdefault("payment", {})["wechat_name"] = os.environ["JL_AGENT_WECHAT_NAME"]
    if os.environ.get("JL_AGENT_PAYMENT_NOTE"):
        cfg.setdefault("payment", {})["note"] = os.environ["JL_AGENT_PAYMENT_NOTE"]
    return cfg

def _write_runtime_config(cfg):
    os.makedirs(os.path.dirname(CONFIG_FILE), exist_ok=True)
    tmp = CONFIG_FILE + f".{os.getpid()}.{uuid.uuid4().hex[:8]}.tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(cfg, f, indent=2, ensure_ascii=False)
        f.write("\n")
    os.replace(tmp, CONFIG_FILE)

def load_runtime_config(quiet=False):
    global API_URL, API_KEY, MODEL, MAX_TURNS, MAX_CONTEXT_CHARS, RECENT_CHATS_N, MEMORY_DIR
    created = False
    raw = {}
    if not os.path.exists(CONFIG_FILE):
        raw = {}
        created = True
    else:
        try:
            with open(CONFIG_FILE, encoding="utf-8") as f:
                raw = json.load(f)
        except Exception:
            corrupt = CONFIG_FILE + ".corrupt." + datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
            try:
                shutil.copy2(CONFIG_FILE, corrupt)
            except:
                pass
            raw = {}
            created = True
            if not quiet:
                print(f"[配置] 配置文件损坏，已备份并重建: {corrupt}")
    cfg = _merge_runtime_config(raw)
    if created:
        _write_runtime_config(cfg)
        if not quiet:
            print(f"[首次运行] 已自动创建配置文件: {CONFIG_FILE}")
            print(f"[首次运行] 修改这个 JSON 文件即可更新 API 配置；打包 exe 后也不需要重打包")
    else:
        # 自动补齐新增字段，但保留用户已有配置。
        try:
            if cfg != raw:
                _write_runtime_config(cfg)
        except:
            pass
    API_URL = str(cfg.get("api", {}).get("url", "") or "").strip()
    API_KEY = str(cfg.get("api", {}).get("key", "") or "")
    MODEL = str(cfg.get("api", {}).get("model", "") or "").strip()
    agent_cfg = cfg.get("agent", {}) or {}
    try: MAX_TURNS = int(agent_cfg.get("max_turns", MAX_TURNS))
    except: pass
    try: MAX_CONTEXT_CHARS = int(agent_cfg.get("max_context_chars", MAX_CONTEXT_CHARS))
    except: pass
    try: RECENT_CHATS_N = int(agent_cfg.get("recent_chats_to_inject", RECENT_CHATS_N))
    except: pass
    MEMORY_DIR = str((cfg.get("memory", {}) or {}).get("db_dir", MEMORY_DIR) or MEMORY_DIR)
    return cfg

