# ====== API 调用封装 ======
def api_call(payload, timeout=120):
    headers = {"Content-Type": "application/json"}
    if API_KEY:
        headers["Authorization"] = f"Bearer {API_KEY}"
    # 本地地址不走代理（避免 Shadowrocket 等工具干扰）
    no_proxy = {"http": None, "https": None}
    try:
        r = requests.post(API_URL, json=payload, headers=headers, timeout=timeout, proxies=no_proxy)
        if r.status_code != 200:
            err = r.json().get("error", {}).get("message", r.text[:200])
            return {"error": f"API错误 {r.status_code}: {err}"}
        return r.json()
    except requests.exceptions.Timeout:
        return {"error": f"API超时（{timeout}s）"}
    except Exception as e:
        return {"error": str(e)}

def api_stream_call(payload, timeout=120):
    headers = {"Content-Type": "application/json"}
    if API_KEY:
        headers["Authorization"] = f"Bearer {API_KEY}"
    no_proxy = {"http": None, "https": None}
    stream_payload = dict(payload or {})
    stream_payload["stream"] = True
    try:
        with requests.post(API_URL, json=stream_payload, headers=headers, timeout=timeout, proxies=no_proxy, stream=True) as r:
            if r.status_code != 200:
                try:
                    err = r.json().get("error", {}).get("message", r.text[:200])
                except:
                    err = r.text[:200]
                yield {"error": f"API错误 {r.status_code}: {err}"}
                return
            for raw_line in r.iter_lines(decode_unicode=True):
                if not raw_line:
                    continue
                line = raw_line.strip()
                if not line.startswith("data:"):
                    continue
                data = line[5:].strip()
                if not data or data == "[DONE]":
                    continue
                try:
                    yield json.loads(data)
                except Exception as e:
                    yield {"error": f"流解析失败: {e}"}
                    return
    except requests.exceptions.Timeout:
        yield {"error": f"API超时（{timeout}s）"}
    except Exception as e:
        yield {"error": str(e)}

def _should_retry_api_error(err_text):
    text = (err_text or "").lower()
    hard_fail_keys = [
        "insufficient balance",
        "余额不足",
        "quota",
        "credit",
        "payment required",
        "api错误 401",
        "api错误 402",
        "api错误 403",
        "invalid api key",
        "unauthorized",
    ]
    return not any(key in text for key in hard_fail_keys)

def _friendly_api_error(err_text):
    text = str(err_text or "").strip()
    low = text.lower()
    if "insufficient balance" in low or "余额不足" in text or "api错误 402" in low:
        return "API 余额不足（402）。请充值或更换可用模型/API Key 后再试。"
    if "invalid api key" in low or "unauthorized" in low or "api错误 401" in low:
        return "API Key 无效或未授权（401）。请检查配置。"
    if "api错误 403" in low:
        return "API 被拒绝访问（403）。请检查模型权限或账户状态。"
    return text

def _extract_message_text(msg):
    """兼容不同模型的回复字段，优先取用户可见回答。"""
    if not isinstance(msg, dict):
        return str(msg or "")
    content = msg.get("content")
    if isinstance(content, str) and content.strip():
        return content
    if isinstance(content, list):
        parts = []
        for item in content:
            if isinstance(item, dict):
                if item.get("type") == "text" and item.get("text"):
                    parts.append(str(item.get("text")))
                elif item.get("type") == "output_text" and item.get("text"):
                    parts.append(str(item.get("text")))
            elif item:
                parts.append(str(item))
        text = "\n".join(p for p in parts if p).strip()
        if text:
            return text
    reasoning = msg.get("reasoning_content")
    if isinstance(reasoning, str) and reasoning.strip():
        return reasoning
    return ""

def _test_api():
    """快速检查 API 是否可达"""
    try:
        import urllib.request as _ur
        _u = API_URL.replace("/v1/chat/completions", "/v1/models") or API_URL
        _ur.urlopen(_u, timeout=3)
        return True
    except:
        return False

def _try_write_file_in_dir(folder):
    try:
        os.makedirs(folder, exist_ok=True)
        probe = os.path.join(folder, ".jl_agent_self_check_write.tmp")
        with open(probe, "w", encoding="utf-8") as f:
            f.write(datetime.datetime.now().isoformat())
        os.remove(probe)
        return True, ""
    except Exception as e:
        return False, str(e)

def _port_available(host="127.0.0.1", port=18888):
    try:
        import socket
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        try:
            return s.connect_ex((host, int(port))) != 0
        finally:
            s.close()
    except Exception:
        return False

def collect_self_check(check_api=False):
    checks = []
    def add(name, status, detail=""):
        checks.append({"name": name, "status": status, "detail": str(detail or "")})

    add("Python/EXE", "OK", f"python={sys.version.split()[0]}, frozen={bool(getattr(sys, 'frozen', False))}, platform={platform.platform()}")
    add("配置文件", "OK" if os.path.exists(CONFIG_FILE) else "WARN", CONFIG_FILE)
    try:
        cfg = load_runtime_config(quiet=True)
        api = cfg.get("api", {}) or {}
        if not api.get("url") or not api.get("model"):
            add("API配置", "FAIL", "api.url 或 api.model 为空")
        else:
            key_state = "已配置" if api.get("key") else "空（本地/内网无鉴权时可接受）"
            add("API配置", "OK", f"url={api.get('url')}, model={api.get('model')}, key={key_state}")
    except Exception as e:
        add("API配置", "FAIL", e)

    add("当前系统", "OK", platform.platform())
    add("个人数据目录", "OK", PERSONAL_DATA_DIR)
    add("共享数据目录", "OK", SHARE_DATA_DIR)

    for label, path in (("个人数据写入", PERSONAL_DATA_DIR), ("共享数据写入", SHARE_DATA_DIR)):
        ok, err = _try_write_file_in_dir(path)
        add(label, "OK" if ok else "FAIL", path if ok else f"{path}: {err}")

    try:
        os.makedirs(os.path.dirname(MEMORY_DB), exist_ok=True)
        conn = sqlite3.connect(MEMORY_DB)
        conn.execute("CREATE TABLE IF NOT EXISTS _self_check(key TEXT PRIMARY KEY, value TEXT)")
        conn.execute("INSERT OR REPLACE INTO _self_check VALUES('last_run', ?)", (datetime.datetime.now().isoformat(),))
        conn.commit()
        conn.close()
        add("本地记忆库", "OK", MEMORY_DB)
    except Exception as e:
        add("本地记忆库", "FAIL", e)

    try:
        skill_count = len([f for f in os.listdir(SKILLS_DIR) if f.endswith(".md")]) if os.path.isdir(SKILLS_DIR) else 0
        add("技能目录", "OK" if skill_count > 0 else "WARN", f"{SKILLS_DIR} / {skill_count} 个技能")
    except Exception as e:
        add("技能目录", "FAIL", e)

    try:
        kb_dir = os.path.join(SHARE_DATA_DIR, "knowledge")
        kb_count = len([f for f in os.listdir(kb_dir) if f.endswith(".txt")]) if os.path.isdir(kb_dir) else 0
        add("共享知识库", "OK" if kb_count > 0 else "WARN", f"{kb_dir} / {kb_count} 个文本")
    except Exception as e:
        add("共享知识库", "WARN", e)

    try:
        os.makedirs(os.path.dirname(USERS_FILE), exist_ok=True)
        if not os.path.exists(USERS_FILE):
            add("用户权限文件", "WARN", f"尚未创建，首次启动会生成: {USERS_FILE}")
        else:
            with open(USERS_FILE, encoding="utf-8") as f:
                data = json.load(f)
            add("用户权限文件", "OK", f"{USERS_FILE} / users={len(data.get('users', {}))}")
    except Exception as e:
        add("用户权限文件", "FAIL", e)

    required_modules = ["requests", "sqlite3"]
    optional_modules = ["openpyxl", "fitz", "rich", "prompt_toolkit"]
    for mod_name in required_modules + optional_modules:
        try:
            __import__(mod_name)
            add(f"依赖:{mod_name}", "OK", "")
        except Exception as e:
            status = "FAIL" if mod_name in required_modules else "WARN"
            add(f"依赖:{mod_name}", status, e)

    add("Dashboard端口", "OK" if _port_available("127.0.0.1", PORT if 'PORT' in globals() else 18888) else "WARN",
        f"127.0.0.1:{PORT if 'PORT' in globals() else 18888} " + ("可用" if _port_available("127.0.0.1", PORT if 'PORT' in globals() else 18888) else "可能已被占用"))

    try:
        pay = payment_settings()
        qr_path = pay.get("wechat_qr", "")
        qr_ok = bool(qr_path and os.path.exists(qr_path) and os.path.isfile(qr_path))
        add("微信收款码", "OK" if qr_ok else "WARN", qr_path if qr_path else "未配置；可设置 payment/wechat_qr.png 或 JL_AGENT_WECHAT_QR")
    except Exception as e:
        add("微信收款码", "WARN", e)

    if shutil.which("curl"):
        add("curl", "OK", shutil.which("curl"))
    else:
        add("curl", "WARN", "Dashboard非流式fallback会用到curl；Win10/Win11通常自带")

    if check_api:
        add("API连通性", "OK" if _test_api() else "FAIL", API_URL)
    else:
        add("API连通性", "SKIP", "未执行；需要时运行 --self-check-api")

    has_fail = any(i["status"] == "FAIL" for i in checks)
    return checks, 1 if has_fail else 0

def format_self_check(checks):
    width = max([len(i["name"]) for i in checks] + [8])
    lines = [
        "JL-Agent 运行环境自检",
        "=" * 60,
    ]
    for item in checks:
        status = item["status"]
        mark = "[OK]" if status == "OK" else "[!!]" if status == "WARN" else "[X]" if status == "FAIL" else "[--]"
        lines.append(f"{mark} {item['name']:<{width}} {item['detail']}")
    lines.append("=" * 60)
    if any(i["status"] == "FAIL" for i in checks):
        lines.append("结果: 有失败项，需要先修复再给同事使用。")
    elif any(i["status"] == "WARN" for i in checks):
        lines.append("结果: 可运行，但有警告项，建议按上面提示确认。")
    else:
        lines.append("结果: 基础环境通过。")
    return "\n".join(lines)

def run_self_check(check_api=False):
    checks, code = collect_self_check(check_api=check_api)
    print(format_self_check(checks))
    return code

def _project_root():
    if getattr(sys, "frozen", False):
        candidates = [os.getcwd(), os.path.dirname(os.path.abspath(sys.executable))]
        for candidate in candidates:
            try:
                if any(os.path.exists(os.path.join(candidate, marker)) for marker in ("xjlagent.py", "README.md", ".gitignore")):
                    return os.path.abspath(candidate)
            except Exception:
                pass
        return os.getcwd()
    try:
        return os.path.dirname(os.path.abspath(__file__))
    except Exception:
        return os.getcwd()

def _safe_rel(path, root):
    try:
        return os.path.relpath(path, root).replace("\\", "/")
    except Exception:
        return str(path)

def collect_release_check():
    root = _project_root()
    checks = []
    def add(name, status, detail=""):
        checks.append({"name": name, "status": status, "detail": str(detail or "")})

    add("项目目录", "OK", root)
    for rel in (".gitignore", "README.md", "config.example.json", "SECURITY.md"):
        add(rel, "OK" if os.path.exists(os.path.join(root, rel)) else "FAIL", rel)

    source_file = os.path.join(root, "xjlagent.py")
    add("主程序", "OK" if os.path.exists(source_file) else "FAIL", "xjlagent.py")
    add("打包配置", "OK" if os.path.exists(os.path.join(root, "xjlagent.spec")) else "WARN", "xjlagent.spec")

    risky_present = []
    risky_name_patterns = [
        re.compile(r"(^|/)\.myagent(/|$)", re.I),
        re.compile(r"(^|/)__pycache__(/|$)", re.I),
        re.compile(r"(^|/)(build|dist|wheels)(/|$)", re.I),
        re.compile(r"(^|/)myagent_config.*\.json$", re.I),
        re.compile(r"(^|/)claude_.*openrouter.*\.bat$", re.I),
        re.compile(r"(^|/)skills/\.(curator_state|bundled_manifest|usage\.json|usage\.json\.lock)$", re.I),
        re.compile(r"\.bak($|[._-])", re.I),
        re.compile(r"\.(db|sqlite|log|jsonl|xlsx|xls|pdf|wps|whl|tar\.gz)$", re.I),
        re.compile(r"(^|/)(daily_|crawl_|safe_|~\$)", re.I),
    ]
    skip_dirs = {".git", ".idea", "__pycache__", ".myagent", "build", "dist", "wheels"}
    scan_exts = {".py", ".bat", ".cmd", ".ps1", ".sh", ".md", ".txt", ".json", ".spec"}
    secret_patterns = [
        ("API key", re.compile(r"sk-[A-Za-z0-9_-]{16,}")),
        ("Bearer token", re.compile(r"Bearer\s+[A-Za-z0-9._~+/=-]{20,}", re.I)),
        ("private key", re.compile(r"-----BEGIN [A-Z ]*PRIVATE KEY-----")),
    ]
    secret_hits = []
    scanned = 0
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in skip_dirs]
        for filename in filenames:
            path = os.path.join(dirpath, filename)
            rel = _safe_rel(path, root)
            is_risky = any(p.search(rel) for p in risky_name_patterns)
            if is_risky:
                risky_present.append(rel)
                continue
            ext = os.path.splitext(filename)[1].lower()
            if ext not in scan_exts:
                continue
            if len(secret_hits) >= 20:
                continue
            try:
                if os.path.getsize(path) > 12 * 1024 * 1024:
                    continue
                with open(path, "r", encoding="utf-8", errors="ignore") as f:
                    text = f.read()
                scanned += 1
            except Exception:
                continue
            for label, pattern in secret_patterns:
                if pattern.search(text):
                    secret_hits.append(f"{rel} ({label})")
                    break

    add("敏感信息扫描", "FAIL" if secret_hits else "OK",
        "疑似敏感内容: " + ", ".join(secret_hits[:10]) if secret_hits else f"扫描 {scanned} 个文本文件，未发现常见密钥模式")
    if risky_present:
        sample = ", ".join(risky_present[:12])
        more = "" if len(risky_present) <= 12 else f" ... 另有 {len(risky_present) - 12} 个"
        add("本地私有/生成文件", "WARN", sample + more)
    else:
        add("本地私有/生成文件", "OK", "未发现明显运行数据或生成文件")

    if os.path.exists(os.path.join(root, ".git")):
        add("Git仓库", "OK", "已初始化")
    else:
        add("Git仓库", "WARN", "当前目录还不是git仓库；发布前先执行 git init 或在GitHub Desktop中创建仓库")

    has_fail = any(i["status"] == "FAIL" for i in checks)
    return checks, 1 if has_fail else 0

def format_release_check(checks):
    width = max([len(i["name"]) for i in checks] + [8])
    lines = [
        "JL-Agent GitHub发布自检",
        "=" * 60,
    ]
    for item in checks:
        status = item["status"]
        mark = "[OK]" if status == "OK" else "[!!]" if status == "WARN" else "[X]" if status == "FAIL" else "[--]"
        lines.append(f"{mark} {item['name']:<{width}} {item['detail']}")
    lines.append("=" * 60)
    if any(i["status"] == "FAIL" for i in checks):
        lines.append("结果: 暂不建议公开发布；先修复 FAIL 项。")
    elif any(i["status"] == "WARN" for i in checks):
        lines.append("结果: 可以准备发布，但需要确认 WARN 项不会被提交。")
    else:
        lines.append("结果: 发布前基础检查通过。")
    return "\n".join(lines)

def run_release_check():
    checks, code = collect_release_check()
    print(format_release_check(checks))
    return code

def _engineering_plan_file():
    return os.path.join(PERSONAL_DATA_DIR, "engineering_plan.json")

def _load_engineering_plan():
    fp = _engineering_plan_file()
    if not os.path.exists(fp):
        return {"title": "", "items": [], "updated_at": ""}
    try:
        with open(fp, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict):
            raise ValueError("plan root must be object")
        data.setdefault("title", "")
        data.setdefault("items", [])
        data.setdefault("updated_at", "")
        return data
    except Exception:
        return {"title": "", "items": [], "updated_at": ""}

def _save_engineering_plan(data):
    fp = _engineering_plan_file()
    os.makedirs(os.path.dirname(fp), exist_ok=True)
    data["updated_at"] = datetime.datetime.now().isoformat()
    tmp = fp + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
        f.write("\n")
    os.replace(tmp, fp)
    return fp

def update_engineering_plan(action="show", text="", index=None):
    action = (action or "show").strip().lower()
    data = _load_engineering_plan()
    if action in ("new", "reset"):
        data = {"title": str(text or "未命名任务").strip(), "items": [], "updated_at": ""}
        _save_engineering_plan(data)
    elif action == "add":
        item_text = str(text or "").strip()
        if not item_text:
            return {"error": "add 需要步骤内容"}
        data.setdefault("items", []).append({"step": item_text, "status": "pending"})
        _save_engineering_plan(data)
    elif action in ("done", "complete", "todo", "pending", "start", "in_progress"):
        try:
            pos = int(index) - 1
        except Exception:
            return {"error": "需要有效的步骤序号"}
        items = data.setdefault("items", [])
        if pos < 0 or pos >= len(items):
            return {"error": "步骤序号超出范围"}
        status = "completed" if action in ("done", "complete") else "in_progress" if action in ("start", "in_progress") else "pending"
        items[pos]["status"] = status
        _save_engineering_plan(data)
    elif action == "clear":
        data = {"title": "", "items": [], "updated_at": ""}
        _save_engineering_plan(data)
    elif action in ("show", "list", ""):
        pass
    else:
        return {"error": f"未知 plan 动作: {action}"}
    return data

def format_engineering_plan(data):
    title = data.get("title") or "当前没有任务计划"
    items = data.get("items") or []
    lines = [f"任务计划: {title}"]
    if data.get("updated_at"):
        lines.append(f"更新时间: {data.get('updated_at')}")
    if not items:
        lines.append("暂无步骤。")
        lines.append("用法: /plan new <标题> | /plan add <步骤> | /plan start 1 | /plan done 1 | /plan clear")
        return "\n".join(lines)
    mark = {"pending": "[ ]", "in_progress": "[>]", "completed": "[x]"}
    for i, item in enumerate(items, 1):
        lines.append(f"{i}. {mark.get(item.get('status'), '[ ]')} {item.get('step', '')}")
    return "\n".join(lines)

def _resolve_project_root(path="."):
    markers = (
        ".git", "pyproject.toml", "requirements.txt", "package.json", "Cargo.toml",
        "go.mod", "pom.xml", "build.gradle", "xjlagent.py", "README.md"
    )
    try:
        if not path or str(path).strip() in (".", "./"):
            start = _project_root()
        else:
            start = resolve_user_path(path or ".", must_exist=True)
    except Exception:
        start = os.path.abspath(path or ".")
    if os.path.isfile(start):
        start = os.path.dirname(start)
    cur = os.path.abspath(start)
    while True:
        if any(os.path.exists(os.path.join(cur, marker)) for marker in markers):
            return cur
        parent = os.path.dirname(cur)
        if parent == cur:
            return os.path.abspath(start)
        cur = parent

def _run_quick(args, cwd=None, timeout=8):
    try:
        r = subprocess.run(args, cwd=cwd, capture_output=True, text=True, timeout=timeout, encoding="utf-8", errors="replace")
        return {"ok": r.returncode == 0, "exit_code": r.returncode, "stdout": (r.stdout or "").strip(), "stderr": (r.stderr or "").strip()}
    except Exception as e:
        return {"ok": False, "exit_code": None, "stdout": "", "stderr": str(e)}

def _git_status_summary(root):
    if not shutil.which("git"):
        return {"is_git": False, "detail": "git 不在 PATH 中"}
    probe = _run_quick(["git", "-C", root, "rev-parse", "--is-inside-work-tree"], timeout=5)
    if not probe.get("ok") or probe.get("stdout") != "true":
        return {"is_git": False, "detail": "不是 git 工作树"}
    branch = _run_quick(["git", "-C", root, "rev-parse", "--abbrev-ref", "HEAD"], timeout=5).get("stdout", "")
    top = _run_quick(["git", "-C", root, "rev-parse", "--show-toplevel"], timeout=5).get("stdout", root)
    status_raw = _run_quick(["git", "-C", root, "status", "--porcelain=v1"], timeout=8).get("stdout", "")
    files = []
    counts = {"modified": 0, "added": 0, "deleted": 0, "renamed": 0, "untracked": 0, "other": 0}
    for line in status_raw.splitlines():
        if not line:
            continue
        code = line[:2]
        name = line[3:].strip()
        if code == "??":
            counts["untracked"] += 1
            kind = "untracked"
        elif "D" in code:
            counts["deleted"] += 1
            kind = "deleted"
        elif "R" in code:
            counts["renamed"] += 1
            kind = "renamed"
        elif "A" in code:
            counts["added"] += 1
            kind = "added"
        elif "M" in code:
            counts["modified"] += 1
            kind = "modified"
        else:
            counts["other"] += 1
            kind = "other"
        files.append({"code": code, "kind": kind, "path": name})
    last = _run_quick(["git", "-C", root, "log", "-1", "--pretty=%h %ad %s", "--date=short"], timeout=5)
    return {
        "is_git": True,
        "root": top or root,
        "branch": branch,
        "clean": not bool(files),
        "counts": counts,
        "files": files[:80],
        "total_changed": len(files),
        "last_commit": last.get("stdout", "") if last.get("ok") else "",
    }

def collect_worktree_summary(path="."):
    root = _resolve_project_root(path)
    git = _git_status_summary(root)
    if git.get("is_git"):
        return {"path": path, "root": root, "git": git}
    local_changes = []
    for name in ("myagent_config.json", ".myagent", "dist", "build", "__pycache__"):
        p = os.path.join(root, name)
        if os.path.exists(p):
            local_changes.append(name)
    return {"path": path, "root": root, "git": git, "local_runtime_items": local_changes}

def format_worktree_summary(info):
    lines = [f"工作树: {info.get('root')}"]
    git = info.get("git", {})
    if not git.get("is_git"):
        lines.append(f"Git: {git.get('detail', '不可用')}")
        extras = info.get("local_runtime_items") or []
        if extras:
            lines.append("发现本地运行/生成项: " + ", ".join(extras))
        return "\n".join(lines)
    lines.append(f"Git: branch={git.get('branch') or '-'} clean={git.get('clean')}")
    if git.get("last_commit"):
        lines.append("Last: " + git.get("last_commit"))
    counts = git.get("counts", {})
    lines.append("变更统计: " + ", ".join(f"{k}={v}" for k, v in counts.items() if v))
    if git.get("clean"):
        lines.append("没有未提交变更。")
    else:
        lines.append("变更文件:")
        for item in (git.get("files") or [])[:30]:
            lines.append(f"  {item.get('code')} {item.get('path')}")
        if git.get("total_changed", 0) > 30:
            lines.append(f"  ... 另有 {git.get('total_changed') - 30} 个")
    return "\n".join(lines)

def collect_project_scan(path=".", max_files=5000):
    root = _resolve_project_root(path)
    skip_dirs = {".git", "__pycache__", ".myagent", "node_modules", "venv", ".venv", "dist", "build", "wheels", ".idea", ".vscode"}
    marker_files = [
        "README.md", "README.txt", "pyproject.toml", "requirements.txt", "setup.py", "package.json",
        "xjlagent.py", "xjlagent.spec", "build_xjlagent_exe.bat", "prepare_offline_wheels.bat",
        "config.example.json", "SECURITY.md"
    ]
    languages = {}
    important = []
    total_files = 0
    total_dirs = 0
    largest = []
    ext_map = {
        ".py": "Python", ".js": "JavaScript", ".ts": "TypeScript", ".tsx": "TypeScript",
        ".jsx": "JavaScript", ".md": "Markdown", ".json": "JSON", ".bat": "Batch",
        ".ps1": "PowerShell", ".sh": "Shell", ".sql": "SQL", ".html": "HTML",
        ".css": "CSS", ".xlsx": "Excel", ".pdf": "PDF"
    }
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in skip_dirs and not (d.startswith(".") and d not in (".github",))]
        total_dirs += len(dirnames)
        for filename in filenames:
            total_files += 1
            if total_files > max_files:
                break
            fp = os.path.join(dirpath, filename)
            rel = _safe_rel(fp, root)
            ext = os.path.splitext(filename)[1].lower()
            lang = ext_map.get(ext)
            if lang:
                languages[lang] = languages.get(lang, 0) + 1
            if filename in marker_files or rel.startswith(".github/"):
                important.append(rel)
            try:
                size = os.path.getsize(fp)
                largest.append((size, rel))
                largest = sorted(largest, reverse=True)[:8]
            except Exception:
                pass
        if total_files > max_files:
            break
    markers = [m for m in marker_files if os.path.exists(os.path.join(root, m))]
    verify = suggest_verify_commands(root, markers=markers, languages=languages)
    return {
        "root": root,
        "markers": markers,
        "languages": dict(sorted(languages.items(), key=lambda kv: kv[1], reverse=True)),
        "important_files": sorted(set(important))[:40],
        "total_files_seen": total_files,
        "total_dirs_seen": total_dirs,
        "largest_files": [{"path": rel, "size_bytes": size} for size, rel in largest],
        "worktree": collect_worktree_summary(root).get("git", {}),
        "verify_commands": verify,
        "stopped_early": total_files > max_files,
    }

def suggest_verify_commands(root, markers=None, languages=None):
    markers = markers or []
    languages = languages or {}
    commands = []
    if "xjlagent.py" in markers:
        commands.append("python xjlagent.py --self-check")
        commands.append("python xjlagent.py --release-check")
    if "pyproject.toml" in markers:
        commands.append("python -m py_compile <changed .py files>")
        commands.append("python -m pytest")
    elif "requirements.txt" in markers or languages.get("Python"):
        commands.append("python -m py_compile <changed .py files>")
    if "package.json" in markers:
        commands.append("npm test")
        commands.append("npm run build")
    if "build_xjlagent_exe.bat" in markers and IS_WINDOWS:
        commands.append("build_xjlagent_exe.bat --no-pause")
    if not commands:
        commands.append("根据变更文件选择最小可运行验证")
    return commands

def format_project_scan(info):
    lines = [f"项目扫描: {info.get('root')}"]
    if info.get("markers"):
        lines.append("关键标记: " + ", ".join(info.get("markers")))
    if info.get("languages"):
        lines.append("语言/文件类型: " + ", ".join(f"{k}={v}" for k, v in info.get("languages", {}).items()))
    lines.append(f"文件/目录: files={info.get('total_files_seen')} dirs={info.get('total_dirs_seen')}")
    git = info.get("worktree", {})
    if git.get("is_git"):
        lines.append(f"Git: branch={git.get('branch') or '-'} clean={git.get('clean')}")
    else:
        lines.append("Git: " + git.get("detail", "不可用"))
    if info.get("important_files"):
        lines.append("重点文件:")
        for rel in info.get("important_files", [])[:20]:
            lines.append(f"  - {rel}")
    if info.get("verify_commands"):
        lines.append("建议验证:")
        for cmd in info.get("verify_commands"):
            lines.append(f"  - {cmd}")
    return "\n".join(lines)

def _redact_text_for_log(text):
    s = str(text or "")
    s = re.sub(r"sk-[A-Za-z0-9_-]{8,}", "sk-***REDACTED***", s)
    s = re.sub(r"Bearer\s+[A-Za-z0-9._~+/=-]{12,}", "Bearer ***REDACTED***", s, flags=re.I)
    s = re.sub(r"(?i)(api[_-]?key|token|password|secret)(['\"\s:=]+)([^'\"\s,;}]+)", r"\1\2***REDACTED***", s)
    return s

def _audit_log_file():
    return os.path.join(PERSONAL_DATA_DIR, "tool_audit.jsonl")

def _summarize_for_audit(value, depth=0):
    if depth > 2:
        return "<nested>"
    if isinstance(value, dict):
        out = {}
        for k, v in value.items():
            kl = str(k).lower()
            if kl in ("content", "code", "api_key", "key", "token", "password", "secret"):
                out[k] = f"<redacted {len(str(v or ''))} chars>"
            else:
                out[k] = _summarize_for_audit(v, depth + 1)
        return out
    if isinstance(value, list):
        return [_summarize_for_audit(v, depth + 1) for v in value[:8]]
    text = _redact_text_for_log(str(value))
    return text[:500] + ("..." if len(text) > 500 else "")

def append_audit_event(event_type, name="", args=None, result=None, status="ok", detail=""):
    try:
        os.makedirs(PERSONAL_DATA_DIR, exist_ok=True)
        event = {
            "time": datetime.datetime.now().isoformat(),
            "event": event_type,
            "tool": name,
            "user": get_user_identity() if "get_user_identity" in globals() else "",
            "status": status,
            "args": _summarize_for_audit(args or {}),
            "result": _summarize_for_audit(result or {}),
            "detail": _redact_text_for_log(detail)[:500],
        }
        with open(_audit_log_file(), "a", encoding="utf-8") as f:
            f.write(json.dumps(event, ensure_ascii=False) + "\n")
    except Exception:
        pass

def load_recent_audit(limit=30):
    fp = _audit_log_file()
    if not os.path.exists(fp):
        return []
    try:
        with open(fp, "r", encoding="utf-8", errors="replace") as f:
            lines = f.readlines()[-max(1, int(limit or 30)):]
        out = []
        for line in lines:
            try:
                out.append(json.loads(line))
            except Exception:
                pass
        return out
    except Exception:
        return []

def format_audit_log(events):
    lines = [f"工具审计日志: {_audit_log_file()}"]
    if not events:
        lines.append("暂无记录。")
        return "\n".join(lines)
    for item in events:
        lines.append(f"- {item.get('time')} [{item.get('status')}] {item.get('event')}:{item.get('tool')} {item.get('detail')}")
    return "\n".join(lines)

def _command_safety_check(command):
    raw = str(command or "").strip()
    low = raw.lower()
    if not raw:
        return {"ok": False, "level": "fail", "reason": "空命令"}
    if os.environ.get("JL_AGENT_ALLOW_DANGEROUS", "").lower() in ("1", "true", "yes"):
        return {"ok": True, "level": "override", "reason": "JL_AGENT_ALLOW_DANGEROUS 已开启"}
    if raw.startswith("ALLOW_DANGEROUS:"):
        return {"ok": True, "level": "override", "command": raw.split(":", 1)[1].strip(), "reason": "命令显式确认"}
    dangerous_patterns = [
        (r"\brm\s+-[^;\n]*[rf][^;\n]*\s+(/|\*|~|[a-z]:\\)", "递归删除高风险路径"),
        (r"\b(del|erase)\s+[^;\n]*(/s|/q)[^;\n]*(\*|\\|/)", "批量删除命令"),
        (r"\b(rmdir|rd)\s+[^;\n]*/s", "递归删除目录"),
        (r"\bformat\s+[a-z]:", "格式化磁盘"),
        (r"\bdiskpart\b", "磁盘分区工具"),
        (r"\bmkfs(?:\.|\b)", "格式化文件系统"),
        (r"\bshutdown\b|\breboot\b", "关机/重启"),
        (r"\bgit\s+reset\s+--hard\b", "强制重置 git 工作树"),
        (r"\bgit\s+clean\s+-[^;\n]*[fdx]", "清理未跟踪文件"),
        (r"\bgit\s+(checkout|restore)\s+[^;\n]*(--|\.)", "可能覆盖工作树文件"),
        (r"\b(drop|truncate)\s+database\b|\bdrop\s+table\b", "数据库破坏性操作"),
        (r"\breg\s+delete\b", "删除注册表"),
        (r"\b(?:curl|wget|iwr|invoke-webrequest)[^|\n]*\|\s*(?:sh|bash|iex|powershell)", "下载后直接执行"),
        (r"\bpowershell(?:\.exe)?\s+[^;\n]*(-enc|-encodedcommand)\b", "PowerShell 编码命令"),
    ]
    for pattern, reason in dangerous_patterns:
        if re.search(pattern, low, flags=re.I):
            return {
                "ok": False,
                "level": "block",
                "reason": reason,
                "hint": "如确实需要执行，请人工确认后加前缀 ALLOW_DANGEROUS: 或设置 JL_AGENT_ALLOW_DANGEROUS=1"
            }
    caution_patterns = [
        (r"\bpip\s+install\b", "会修改 Python 环境"),
        (r"\bnpm\s+install\b", "会修改 Node 依赖"),
        (r"\bgit\s+commit\b|\bgit\s+push\b", "会写入/发布 Git 历史"),
        (r"\btaskkill\b|\bkill\s+-9\b", "会终止进程"),
    ]
    for pattern, reason in caution_patterns:
        if re.search(pattern, low, flags=re.I):
            return {"ok": True, "level": "warn", "reason": reason, "command": raw}
    return {"ok": True, "level": "ok", "reason": "", "command": raw}

def _make_unified_diff(path, old_text, new_text, context=3):
    old_lines = str(old_text or "").splitlines(keepends=True)
    new_lines = str(new_text or "").splitlines(keepends=True)
    return "".join(difflib.unified_diff(
        old_lines,
        new_lines,
        fromfile=f"{path} (before)",
        tofile=f"{path} (after)",
        lineterm="",
        n=context,
    ))

def preview_text_patch(path, old_text, new_text, replace_all=False):
    path = resolve_user_path(path, must_exist=True)
    if not os.path.exists(path) or not os.path.isfile(path):
        return {"error": f"文件不存在或不是普通文件: {path}"}
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        content = f.read()
    count = content.count(old_text)
    if count == 0:
        return {"error": "未找到匹配文本"}
    if count > 1 and not replace_all:
        return {"error": f"找到 {count} 处匹配；请提供更精确 old_text 或设置 replace_all"}
    new_content = content.replace(old_text, new_text, -1 if replace_all else 1)
    diff = _make_unified_diff(path, content, new_content)
    return {"ok": True, "path": path, "matches": count if replace_all else 1, "diff": diff[:8000], "truncated": len(diff) > 8000}

def collect_git_diff(path=".", file_path="", staged=False):
    root = _resolve_project_root(path)
    if not shutil.which("git"):
        return {"error": "git 不在 PATH 中", "root": root}
    if not _git_status_summary(root).get("is_git"):
        return {"error": "不是 git 工作树", "root": root}
    cmd = ["git", "-C", root, "diff"]
    if staged:
        cmd.append("--staged")
    if file_path:
        cmd.extend(["--", file_path])
    r = _run_quick(cmd, cwd=root, timeout=12)
    return {"root": root, "exit_code": r.get("exit_code"), "diff": (r.get("stdout") or "")[:12000], "truncated": len(r.get("stdout") or "") > 12000, "stderr": r.get("stderr", "")[:1000]}

def run_verification_pipeline(path=".", commands=None, timeout=180):
    root = _resolve_project_root(path)
    if commands is None:
        commands = collect_project_scan(root, max_files=2500).get("verify_commands", [])
    if isinstance(commands, str):
        commands = [commands]
    results = []
    for command in commands[:8]:
        cmd_text = str(command or "").strip()
        if not cmd_text:
            continue
        if "<changed .py files>" in cmd_text:
            if getattr(sys, "frozen", False):
                results.append({"command": cmd_text, "skipped": True, "reason": "当前是打包后的 exe；跳过源码 py_compile"})
                continue
            py_files = []
            git = _git_status_summary(root)
            if git.get("is_git"):
                for item in git.get("files", []):
                    p = item.get("path", "")
                    if p.endswith(".py") and " -> " not in p:
                        py_files.append(p)
            if not py_files and os.path.exists(os.path.join(root, "xjlagent.py")):
                py_files = ["xjlagent.py"]
            if not py_files:
                results.append({"command": cmd_text, "skipped": True, "reason": "没有找到需要编译的 .py 文件"})
                continue
            for rel in py_files[:20]:
                args = [sys.executable, "-m", "py_compile", rel]
                started = time.time()
                r = subprocess.run(args, cwd=root, capture_output=True, text=True, timeout=timeout, encoding="utf-8", errors="replace")
                results.append({"command": " ".join(args), "exit_code": r.returncode, "elapsed_sec": round(time.time() - started, 2), "stdout": r.stdout[-2000:], "stderr": r.stderr[-2000:]})
            continue
        if getattr(sys, "frozen", False) and "build_xjlagent_exe.bat" in cmd_text.lower():
            results.append({"command": cmd_text, "skipped": True, "reason": "当前 exe 正在运行，不能覆盖自身；请在源码环境执行打包脚本"})
            continue
        safe = _command_safety_check(cmd_text)
        if not safe.get("ok"):
            results.append({"command": cmd_text, "blocked": True, "reason": safe.get("reason"), "hint": safe.get("hint", "")})
            continue
        run_cmd = safe.get("command", cmd_text)
        if run_cmd.startswith("python "):
            run_cmd = f"\"{sys.executable}\" " + run_cmd[len("python "):]
        started = time.time()
        try:
            if IS_WINDOWS:
                r = subprocess.run(run_cmd, cwd=root, shell=True, capture_output=True, text=True, timeout=timeout, encoding="utf-8", errors="replace")
            else:
                r = subprocess.run(run_cmd, cwd=root, shell=True, capture_output=True, text=True, timeout=timeout, encoding="utf-8", errors="replace")
            results.append({"command": run_cmd, "exit_code": r.returncode, "elapsed_sec": round(time.time() - started, 2), "stdout": r.stdout[-3000:], "stderr": r.stderr[-3000:], "warning": safe.get("reason") if safe.get("level") == "warn" else ""})
        except subprocess.TimeoutExpired:
            results.append({"command": run_cmd, "exit_code": None, "elapsed_sec": timeout, "error": "timeout"})
        except Exception as e:
            results.append({"command": run_cmd, "exit_code": None, "error": str(e)})
    append_audit_event("verification", "run_verification", {"path": root, "commands": commands}, {"results": results}, "ok" if all(i.get("exit_code") in (0, None) and not i.get("blocked") for i in results) else "warn")
    return {"root": root, "results": results, "ok": all((i.get("exit_code") == 0 or i.get("skipped")) and not i.get("blocked") for i in results)}

def format_verification_results(data):
    lines = [f"验证流水线: {data.get('root')}"]
    for item in data.get("results", []):
        if item.get("blocked"):
            lines.append(f"[BLOCK] {item.get('command')} - {item.get('reason')}")
        elif item.get("skipped"):
            lines.append(f"[SKIP] {item.get('command')} - {item.get('reason')}")
        else:
            mark = "[OK]" if item.get("exit_code") == 0 else "[X]"
            lines.append(f"{mark} {item.get('command')} ({item.get('elapsed_sec', 0)}s)")
            if item.get("stderr"):
                lines.append("  stderr: " + item.get("stderr", "").strip().splitlines()[-1][:240])
            elif item.get("stdout"):
                lines.append("  stdout: " + item.get("stdout", "").strip().splitlines()[-1][:240])
    lines.append("结果: " + ("通过" if data.get("ok") else "有失败/阻塞项"))
    return "\n".join(lines)

