# ====== 记忆系统 ======
class Memory:
    def __init__(self):
        self.conn = sqlite3.connect(MEMORY_DB)
        self.conn.execute("CREATE TABLE IF NOT EXISTS memory(key TEXT PRIMARY KEY, content TEXT, updated_at TEXT)")
        self.conn.execute("CREATE TABLE IF NOT EXISTS chat_history(id INTEGER PRIMARY KEY AUTOINCREMENT, role TEXT, content TEXT, timestamp TEXT)")
        self.conn.commit()

    def save(self, key, content):
        now = datetime.datetime.now().isoformat()
        self.conn.execute("INSERT OR REPLACE INTO memory(key, content, updated_at) VALUES(?,?,?)", (key, content, now))
        self.conn.commit()

    def delete(self, key):
        self.conn.execute("DELETE FROM memory WHERE key=?", (key,))
        self.conn.commit()

    def load_all(self):
        rows = self.conn.execute("SELECT key, content FROM memory ORDER BY updated_at DESC").fetchall()
        return {r[0]: r[1] for r in rows}

    def search(self, keyword):
        like = f"%{keyword}%"
        rows = self.conn.execute("SELECT key, content FROM memory WHERE key LIKE ? OR content LIKE ?", (like, like)).fetchall()
        return {r[0]: r[1][:500] for r in rows}

    def save_chat(self, role, content):
        self.conn.execute("INSERT INTO chat_history(role, content, timestamp) VALUES(?,?,?)",
                          (role, content[:2000], datetime.datetime.now().isoformat()))
        self.conn.commit()

    def get_recent_chats(self, n=10):
        return self.conn.execute("SELECT role, content FROM chat_history ORDER BY id DESC LIMIT ?", (n,)).fetchall()[::-1]

    def search_chat_history(self, keyword):
        like = f"%{keyword}%"
        rows = self.conn.execute("SELECT role, content, timestamp FROM chat_history WHERE content LIKE ? ORDER BY id DESC LIMIT 20", (like,)).fetchall()
        return [{"role": r[0], "content": r[1][:300], "time": r[2]} for r in rows]

    def close(self):
        self.conn.close()

