    def tool_list_files(self, path="."):
        path = resolve_user_path(path or ".", must_exist=True)
        items = os.listdir(path)
        dirs = [i for i in items if os.path.isdir(os.path.join(path, i))]
        files = [i for i in items if os.path.isfile(os.path.join(path, i))]
        return {"path": path, "directories": dirs, "files": files}

    def tool_patch_file(self, path, old_text, new_text):
        """精确替换文件内容，不改写整个文件"""
        path = resolve_user_path(path, must_exist=True)
        if not os.path.exists(path):
            return {"error": f"文件不存在: {path}"}
        with open(path, encoding="utf-8") as f:
            content = f.read()
        count = content.count(old_text)
        if count == 0:
            return {"error": f"未找到匹配文本（区分大小写，含空格）"}
        if count > 1:
            return {"error": f"找到{count}处匹配，请用更精确的文本"}
        bak = self._backup_file(path)
        old_content = content
        content = content.replace(old_text, new_text, 1)
        with open(path, "w", encoding="utf-8") as f:
            f.write(content)
        diff = _make_unified_diff(path, old_content, content)
        res = {"ok": True, "path": path, "matches": 1, "diff": diff[:3000], "diff_truncated": len(diff) > 3000}
        if bak:
            res["backup"] = bak
        return res

    def tool_file_info(self, path):
        path = resolve_user_path(path, must_exist=True)
        if not os.path.exists(path):
            return {"error": f"文件不存在: {path}"}
        st = os.stat(path)
        info = {
            "path": path,
            "size_bytes": st.st_size,
            "modified": datetime.datetime.fromtimestamp(st.st_mtime).isoformat()
        }
        if os.path.isdir(path):
            try:
                items = os.listdir(path)
                info["type"] = "directory"
                info["entries"] = len(items)
            except Exception as e:
                info["error"] = str(e)
            return info
        try:
            with open(path, encoding="utf-8", errors="replace") as f:
                lines = f.readlines()
            info["type"] = "file"
            info["lines"] = len(lines)
            info["chars"] = sum(len(l) for l in lines)
        except Exception as e:
            info["type"] = "file"
            info["read_error"] = str(e)
        return info

    def tool_analyze_folder(self, path, limit=30, per_file_chars=1200):
        path = resolve_user_path(path, must_exist=True)
        if not os.path.exists(path):
            return {"error": f"路径不存在: {path}"}
        if not os.path.isdir(path):
            return {"error": f"不是文件夹: {path}"}

        exts = {".txt",".md",".json",".csv",".xml",".html",".log",".sql",".ini",".yaml",".yml",".docx",".xlsx",".pdf",".pptx",".py",".js",".ts"}
        files = []
        for root, dirs, names in os.walk(path):
            dirs[:] = [d for d in dirs if d not in ("node_modules", "venv", "__pycache__", ".git", ".myagent") and not d.startswith(".")]
            for name in sorted(names):
                fp = os.path.join(root, name)
                ext = os.path.splitext(name)[1].lower()
                if ext in exts:
                    files.append(fp)
        total_files = len(files)
        files = files[:max(1, int(limit or 30))]

        def _extract_text(fp):
            ext = os.path.splitext(fp)[1].lower()
            try:
                if ext in (".txt",".md",".py",".json",".xml",".csv",".html",".log",".sql",".ini",".yaml",".yml",".js",".ts"):
                    with open(fp, "r", encoding="utf-8", errors="replace") as f:
                        return f.read()
                if ext == ".docx":
                    import zipfile, xml.etree.ElementTree as ET
                    with zipfile.ZipFile(fp) as z:
                        root = ET.fromstring(z.read("word/document.xml"))
                        ns = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
                        return "\n".join(t.text for t in root.iter(f"{{{ns}}}t") if t.text)
                if ext == ".xlsx":
                    import openpyxl
                    wb = openpyxl.load_workbook(fp, read_only=True, data_only=True)
                    lines = []
                    for ws in wb.worksheets:
                        lines.append(f"[Sheet] {ws.title}")
                        row_count = 0
                        for row in ws.iter_rows(values_only=True):
                            vals = [str(c) for c in row if c not in (None, "")]
                            if vals:
                                lines.append(" | ".join(vals))
                                row_count += 1
                            if row_count >= 20:
                                break
                    return "\n".join(lines)
                if ext == ".pptx":
                    import zipfile, xml.etree.ElementTree as ET
                    ns_a = "http://schemas.openxmlformats.org/drawingml/2006/main"
                    slides = []
                    with zipfile.ZipFile(fp) as z:
                        for name in z.namelist():
                            if name.startswith("ppt/slides/slide") and name.endswith(".xml"):
                                root = ET.fromstring(z.read(name))
                                slide_text = "\n".join(t.text for t in root.iter(f"{{{ns_a}}}t") if t.text)
                                if slide_text.strip():
                                    slides.append(slide_text)
                    return "\n\n".join(slides)
                if ext == ".pdf":
                    try:
                        import fitz
                        with fitz.open(fp) as doc:
                            return "\n".join(page.get_text() for page in doc)
                    except Exception as e:
                        return f"[PDF解析失败: {e}]"
            except Exception as e:
                return f"[解析失败: {e}]"
            return ""

        def _guess_category(fp, text):
            rel = os.path.relpath(fp, path)
            ext = os.path.splitext(fp)[1].lower()
            name = os.path.basename(fp).lower()
            sample = (text or "")[:2000].lower()
            if ext in (".xlsx", ".csv"):
                return "表格数据"
            if ext == ".pptx":
                return "演示材料"
            if ext == ".pdf":
                return "PDF资料"
            if any(k in name for k in ("manual","guide","说明","手册","操作")):
                return "说明手册"
            if any(k in sample for k in ("合同","协议","条款","甲方","乙方")):
                return "合同协议"
            if any(k in sample for k in ("需求","方案","设计","接口","流程")):
                return "需求/方案"
            if any(k in sample for k in ("会议","纪要","总结","汇报")):
                return "会议/汇报"
            return "普通文档"

        summary = []
        category_count = {}
        ext_count = {}
        suggestions = []
        for fp in files:
            raw = _extract_text(fp)
            text = re.sub(r"\s+", " ", raw or "").strip()
            text = text[:max(200, int(per_file_chars or 1200))]
            category = _guess_category(fp, text)
            category_count[category] = category_count.get(category, 0) + 1
            ext = os.path.splitext(fp)[1].lower() or "[none]"
            ext_count[ext] = ext_count.get(ext, 0) + 1
            title = os.path.basename(fp)
            preview = text[:300] if text else "[空文件或无法提取文字]"
            risk_flags = []
            if "[PDF解析失败:" in preview or "[解析失败:" in preview:
                risk_flags.append("解析失败")
            if "[空文件或无法提取文字]" in preview:
                risk_flags.append("无可提取文本")
            if any(k in preview.lower() for k in ("todo", "tbd", "placeholder", "待补", "待定", "占位")):
                risk_flags.append("含占位/待补内容")
            if ext == ".xlsx" and any(k in preview for k in ("#REF!", "#DIV/0!", "#VALUE!", "#NAME?")):
                risk_flags.append("表格可能有公式错误")
            if category in ("需求/方案", "合同协议", "说明手册"):
                suggestions.append({"path": fp, "reason": f"{category}，通常值得沉淀到共享知识库"})
            summary.append({
                "path": fp,
                "name": title,
                "ext": ext,
                "category": category,
                "summary": preview,
                "size_bytes": os.path.getsize(fp),
                "risk_flags": risk_flags
            })

        summary.sort(key=lambda x: (x["category"], x["name"]))
        top_dirs = {}
        for fp in files:
            rel = os.path.relpath(fp, path)
            head = rel.split(os.sep)[0] if os.sep in rel else "."
            top_dirs[head] = top_dirs.get(head, 0) + 1
        return {
            "path": path,
            "total_found": total_files,
            "analyzed": len(summary),
            "top_level_groups": top_dirs,
            "extensions": ext_count,
            "categories": category_count,
            "files": summary,
            "knowledge_base_candidates": suggestions[:10]
        }

