    def _ansi_startup(self):
        """ANSI 版启动画面（零依赖版，纯 ASCII）"""
        def _vlen(s):
            return len(re.sub(r'\033\[[0-9;]*m', '', s))
        _G = "\033[1;38;2;255;215;0m"
        _A = "\033[38;2;255;191;0m"
        _B = "\033[38;2;205;127;50m"
        _D = "\033[2m"
        _R = "\033[0m"

        # ASCII 纯文本 Logo（兼容 Windows cmd）
        logo_lines = [
            f"{_G}  XJL-AGENT v2{_R}",
            f"{_A}  -----------{_R}",
            f"{_D}  Tools: {len(TOOLS)}  |  Skills: {len(BUILTIN_SKILLS)}  |  Model: {MODEL.split('/')[-1] if '/' in MODEL else MODEL}{_R}",
            f"{_D}  Memory: .myagent/db{_R}",
        ]
        logo_w = max(_vlen(l) for l in logo_lines)

        # 右侧信息
        model_short = MODEL.split("/")[-1] if "/" in MODEL else MODEL
        if len(model_short) > 30:
            model_short = model_short[:27] + "..."
        info_lines = [
            f"{_D}Tools{_R}",
            f"  {_A}{len(TOOLS)}{_R} available",
            "",
            f"{_D}Skills{_R}",
            f"  {_A}{len(BUILTIN_SKILLS)}{_R} built-in",
            "",
            f"{_D}Memory{_R}",
            f"  {_D}.myagent/db{_R}",
        ]
        info_w = max(_vlen(l) for l in info_lines) if info_lines else 30

        total_w = logo_w + 2 + info_w
        total_w = max(total_w, 50)

        # 顶栏
        title = " JL-Agent v2 "
        pad = (total_w - len(title)) // 2
        print(f"{_D}╭{'─' * pad}{_R}{_G}{title}{_R}{_D}{'─' * (total_w - pad - len(title))}╮{_R}")

        # Logo + 信息 并排
        max_lines = max(len(logo_lines), len(info_lines))
        for i in range(max_lines):
            left = logo_lines[i] if i < len(logo_lines) else " " * logo_w
            right = info_lines[i] if i < len(info_lines) else ""
            vleft = _vlen(left)
            vright = _vlen(right)
            pad_len = total_w - vleft - 2 - vright
            print(f"{_D}│{_R} {left}  {right}{' ' * pad_len}{_D}│{_R}")

        # 底栏
        print(f"{_D}╰{'─' * total_w}╯{_R}")

        # 模型名
        print(f"  {_D}Model: {MODEL}{_R}")
        print()


