def knowledge_lookup(query, by="code"):
    """字典查询。by=code/scenario/keyword"""
    conn = sqlite3.connect(KNOWLEDGE_DB)
    if by == "code":
        r = conn.execute("SELECT * FROM trans_codes WHERE code=?", (query,)).fetchone()
        if r:
            result = "[{0}] {1}-{2}: {3} — {4}".format(r[0], r[1], r[2], r[3], r[4])
            conn.close()
            return result
    elif by == "scenario":
        q = "%" + query + "%"
        r = conn.execute("SELECT * FROM scenario_lookup WHERE scenario LIKE ?", (q,)).fetchall()
        if r:
            result = "\n".join(s[0] + " -> " + s[1] + (" (" + s[2] + ")" if s[2] else "") for s in r)
            conn.close()
            return result
    elif by == "keyword":
        q = "%" + query + "%"
        r = conn.execute("SELECT * FROM trans_codes WHERE scenario LIKE ? OR description LIKE ?", (q, q)).fetchall()
        if r:
            result = "\n".join("[{0}] {1}".format(c[0], c[3]) for c in r)
            conn.close()
            return result
        r = conn.execute("SELECT * FROM policy_index WHERE keywords LIKE ?", (q,)).fetchall()
        if r:
            result = "\n".join(p[3] + " | " + p[4] for p in r)
            conn.close()
            return result
    conn.close()
    return "未查到"


