# ── 主动监控 ──
class MonitorService:
    """轮询监控：外管局政策 / A股市场风险 / 自定义URL"""
    def __init__(self):
        self._watchers = {}

    def watch_safe(self, keyword="", interval_min=60):
        """监控外管局搜索页变化"""
        import hashlib
        name = "safe_" + (keyword or "default")
        url = "https://www.safe.gov.cn/internet_app/search?q=" + keyword + "&siteid=&order=releasetime&page=1"
        try:
            resp = requests.get(url, timeout=15, headers={"User-Agent": "Mozilla/5.0"})
            h = hashlib.md5(resp.text.encode()).hexdigest()
        except Exception:
            h = "error"
        self._watchers[name] = {"url": url, "last_hash": h, "interval": interval_min}
        return name

    def watch_url(self, name, url, interval_min=60):
        """监控任意URL变化"""
        import hashlib
        try:
            resp = requests.get(url, timeout=15, headers={"User-Agent": "Mozilla/5.0"})
            h = hashlib.md5(resp.text.encode()).hexdigest()
        except Exception:
            h = "error"
        self._watchers[name] = {"url": url, "last_hash": h, "interval": interval_min}
        return name

    def check(self):
        """检查所有监控项，返回变化的列表"""
        import hashlib
        alerts = []
        for name, watcher in self._watchers.items():
            try:
                resp = requests.get(watcher["url"], timeout=15, headers={"User-Agent": "Mozilla/5.0"})
                cur = hashlib.md5(resp.text.encode()).hexdigest()
            except Exception:
                continue
            if cur != watcher["last_hash"]:
                alerts.append({"name": name, "url": watcher["url"],
                               "old_hash": watcher["last_hash"], "new_hash": cur})
                watcher["last_hash"] = cur
        return alerts

    def status(self):
        """查看所有监控项状态"""
        lines = []
        for name, w in self._watchers.items():
            lines.append(name + ": " + w['url'][:60] + "...")
        return "\n".join(lines) if lines else "无监控项"

